package solution

type Activation struct {
	Tenant  string
	Feature string
}

func CountActivations(activations []Activation) map[string]map[string]int {
	counts := make(map[string]map[string]int)
	for _, activation := range activations {
		features, ok := counts[activation.Tenant]
		if !ok {
			features = make(map[string]int)
			counts[activation.Tenant] = features
		}
		features[activation.Feature]++
	}
	return counts
}

