	entries := []LedgerEntry{
		{EventID: "duplicate", Account: "first", Delta: 7},
		{EventID: "other", Account: "first", Delta: 3},
		{EventID: "duplicate", Account: "first", Delta: 100},
		{EventID: "duplicate", Account: "second", Delta: -50},
