package solution

import (
	"reflect"
	"testing"
)

func TestGroupMembersConcatenatesByDivisionInInputOrder(t *testing.T) {
	records := []DivisionRecord{
		{Division: "engineering", Members: []string{"Ada", "Grace"}},
		{Division: "sales", Members: []string{"Lin"}},
		{Division: "engineering", Members: []string{"Edsger"}},
		{Division: "sales", Members: []string{"Pat", "Sam"}},
	}
	want := map[string][]string{
		"engineering": {"Ada", "Grace", "Edsger"},
		"sales":       {"Lin", "Pat", "Sam"},
	}

	if got := GroupMembers(records); !reflect.DeepEqual(got, want) {
		t.Fatalf("GroupMembers() = %#v, want %#v", got, want)
	}
}

func TestGroupMembersHandlesEmptyValues(t *testing.T) {
	records := []DivisionRecord{
		{Division: "", Members: []string{"A"}},
		{Division: "empty", Members: nil},
		{Division: "", Members: []string{}},
		{Division: "", Members: []string{"B"}},
	}
	got := GroupMembers(records)

	if !reflect.DeepEqual(got[""], []string{"A", "B"}) {
		t.Fatalf("members for empty division = %#v, want %#v", got[""], []string{"A", "B"})
	}
	if _, exists := got["empty"]; !exists {
		t.Fatal("division with a nil member slice was omitted")
	}
}

func TestGroupMembersEmptyInputReturnsNonNilMap(t *testing.T) {
	for _, records := range [][]DivisionRecord{nil, {}} {
		got := GroupMembers(records)
		if got == nil {
			t.Fatal("GroupMembers() returned a nil map for empty input")
		}
		if len(got) != 0 {
			t.Fatalf("GroupMembers() returned %#v for empty input", got)
		}
	}
}

func TestGroupMembersResultIsIndependentFromInputs(t *testing.T) {
	first := make([]string, 1, 4)
	first[0] = "first"
	second := make([]string, 1, 4)
	second[0] = "second"
	records := []DivisionRecord{
		{Division: "d", Members: first},
		{Division: "d", Members: second},
	}

	got := GroupMembers(records)
	first[0] = "changed-first"
	second[0] = "changed-second"

	if !reflect.DeepEqual(got["d"], []string{"first", "second"}) {
		t.Fatalf("input mutation changed result: %#v", got["d"])
	}
}

func TestGroupMembersInputsAreIndependentFromResult(t *testing.T) {
	members := make([]string, 2, 5)
	members[0], members[1] = "one", "two"
	records := []DivisionRecord{{Division: "d", Members: members}}
	got := GroupMembers(records)

	got["d"][0] = "changed"
	got["d"] = append(got["d"], "three")

	if !reflect.DeepEqual(members, []string{"one", "two"}) {
		t.Fatalf("result mutation changed input: %#v", members)
	}
}

