package solution

func Broadcast(payload []byte, handlers []func([]byte) error) []error {
	results := make([]error, len(handlers))
	for i, handler := range handlers {
		isolated := append([]byte(nil), payload...)
		results[i] = handler(isolated)
	}
	return results
