		return func(message string) {
			calls = append(calls, fmt.Sprintf("handle:%s:%s", id, message))
		}
	}
	listeners := []Listener{
		{ID: "a", Handle: listener("first-a")},
		{ID: "", Handle: listener("empty")},
		{ID: "a", Handle: listener("duplicate-a")},
		{ID: "b", Handle: listener("b")},
		{ID: "", Handle: listener("duplicate-empty")},
	}
	messages := []string{"one", "", "three"}

	Broadcast(listeners, messages, func(id string, count int) {
		calls = append(calls, fmt.Sprintf("done:%s:%d", id, count))
	})

	want := []string{
		"handle:first-a:one", "handle:empty:one", "handle:b:one",
		"handle:first-a:", "handle:empty:", "handle:b:",
		"handle:first-a:three", "handle:empty:three", "handle:b:three",
		"done:a:3", "done::3", "done:b:3",
