	var doneCalls []string
	listeners := []Listener{
		{ID: "x", Handle: func(string) { handles++ }},
		{ID: "x", Handle: func(string) { t.Fatal("duplicate listener was called") }},
		{ID: "y", Handle: func(string) { handles++ }},
	}

	Broadcast(listeners, nil, func(id string, count int) {
		doneCalls = append(doneCalls, fmt.Sprintf("%s:%d", id, count))
