func TestBroadcastWithNoListenersMakesNoCallbacks(t *testing.T) {
	doneCalls := 0
	Broadcast(nil, []string{"one", "two"}, func(string, int) {
		doneCalls++
	})
	if doneCalls != 0 {
		t.Fatalf("done called %d times, want 0", doneCalls)
