package solution

import (
	"strconv"
	"strings"
	"testing"
)

func treeShape(node *TreeNode) string {
	if node == nil {
		return "#"
	}
	var b strings.Builder
	b.WriteString(strconv.Quote(node.Label))
	b.WriteByte('[')
	for i, child := range node.Children {
		if i > 0 {
			b.WriteByte(',')
		}
		b.WriteString(treeShape(child))
	}
	b.WriteByte(']')
	return b.String()
}

func collectTreeNodes(node *TreeNode, nodes map[*TreeNode]struct{}) {
	if node == nil {
		return
	}
	nodes[node] = struct{}{}
	for _, child := range node.Children {
		collectTreeNodes(child, nodes)
	}
}

func assertNoTreeAliases(t *testing.T, input, output *TreeNode) {
	t.Helper()
	inputNodes := make(map[*TreeNode]struct{})
	collectTreeNodes(input, inputNodes)
	var visit func(*TreeNode)
	visit = func(node *TreeNode) {
		if node == nil {
			return
		}
		if _, aliases := inputNodes[node]; aliases {
			t.Fatalf("output node %p aliases an input node", node)
		}
		for _, child := range node.Children {
			visit(child)
		}
	}
	visit(output)
}

func TestMirrorTreeRecursivelyReversesChildrenAndPreservesNilEntries(t *testing.T) {
	a1 := &TreeNode{Label: "a1"}
	a2 := &TreeNode{Label: "a2"}
	a := &TreeNode{Label: "a", Children: []*TreeNode{a1, a2, nil}}
	b1 := &TreeNode{Label: "b1"}
	b := &TreeNode{Label: "b", Children: []*TreeNode{b1}}
	root := &TreeNode{Label: "root", Children: []*TreeNode{a, nil, b}}
	before := treeShape(root)

	mirror := MirrorTree(root)

	want := `"root"["b"["b1"[]],#,"a"[#,"a2"[],"a1"[]]]`
	if got := treeShape(mirror); got != want {
		t.Fatalf("mirrored tree = %s, want %s", got, want)
	}
	if got := treeShape(root); got != before {
		t.Fatalf("MirrorTree modified input: got %s, want %s", got, before)
	}
	assertNoTreeAliases(t, root, mirror)
	if len(root.Children) > 0 && len(mirror.Children) > 0 && &root.Children[0] == &mirror.Children[0] {
		t.Fatal("root Children slice aliases input")
	}
	if len(b.Children) > 0 && len(mirror.Children[0].Children) > 0 && &b.Children[0] == &mirror.Children[0].Children[0] {
		t.Fatal("nested Children slice aliases input")
	}

	mirror.Children[0].Label = "changed"
	mirror.Children[2] = nil
	if got := treeShape(root); got != before {
		t.Fatalf("mutating output affected input: got %s, want %s", got, before)
	}
}

