	root := &TreeNode{Label: "root", Children: make([]*TreeNode, 0, 2)}
	mirror := MirrorTree(root)
	if mirror == nil || mirror == root || len(mirror.Children) != 0 {
		t.Fatalf("unexpected mirror: %#v", mirror)
