	inputChild := &TreeNode{Label: "input child"}
	mirror.Children = append(mirror.Children, mirrorChild)
	root.Children = append(root.Children, inputChild)
	if mirror.Children[0] != mirrorChild {
		t.Fatal("empty output Children slice shares its backing array with input")
