package solution

import (
	"reflect"
	"testing"
)

func parseWithoutPanic(t *testing.T, lines []string) (root *Node, err error) {
	t.Helper()
	defer func() {
		if recovered := recover(); recovered != nil {
			t.Fatalf("ParseOutline panicked for %#v: %v", lines, recovered)
		}
	}()
	return ParseOutline(lines)
}

func TestParseOutlineBuildsTreeInInputOrder(t *testing.T) {
	lines := []string{
		"root",
		"\talpha",
		"\t\tleaf",
		"\tbeta",
		"\t\tchild\tpart",
		"\t\t\tdeep",
		"\tgamma",
	}
	original := append([]string(nil), lines...)

	root, err := parseWithoutPanic(t, lines)
	if err != nil {
		t.Fatalf("ParseOutline returned error for valid input: %v", err)
	}
	if root == nil || root.Name != "root" {
		t.Fatalf("root = %#v, want root node", root)
	}
	if len(root.Children) != 3 {
		t.Fatalf("root has %d children, want 3", len(root.Children))
	}
	alpha, beta, gamma := root.Children[0], root.Children[1], root.Children[2]
	if alpha.Name != "alpha" || beta.Name != "beta" || gamma.Name != "gamma" {
		t.Fatalf("root child order = %q, %q, %q", alpha.Name, beta.Name, gamma.Name)
	}
	if len(alpha.Children) != 1 || alpha.Children[0].Name != "leaf" {
		t.Fatalf("alpha children = %#v, want leaf", alpha.Children)
	}
	if len(beta.Children) != 1 || beta.Children[0].Name != "child\tpart" {
		t.Fatalf("beta children = %#v, want child with embedded tab", beta.Children)
	}
	if len(beta.Children[0].Children) != 1 || beta.Children[0].Children[0].Name != "deep" {
		t.Fatalf("embedded-tab node children = %#v, want deep", beta.Children[0].Children)
	}
	if len(gamma.Children) != 0 {
		t.Fatalf("gamma has %d children, want 0", len(gamma.Children))
	}
	if !reflect.DeepEqual(lines, original) {
		t.Fatalf("ParseOutline modified lines: got %#v, want %#v", lines, original)
	}
}

func TestParseOutlineAcceptsSingleNonemptyRootAndSpaceName(t *testing.T) {
	for _, name := range []string{"root", " "} {
		t.Run(name, func(t *testing.T) {
			root, err := parseWithoutPanic(t, []string{name})
			if err != nil {
				t.Fatalf("unexpected error: %v", err)
			}
			if root == nil || root.Name != name || len(root.Children) != 0 {
				t.Fatalf("root = %#v, want single node named %q", root, name)
			}
		})
	}
}

func TestParseOutlineRejectsMalformedInputWithoutPanicking(t *testing.T) {
	tests := []struct {
		name  string
		lines []string
	}{
		{name: "empty input", lines: nil},
		{name: "empty root name", lines: []string{""}},
		{name: "first line indented", lines: []string{"\troot"}},
		{name: "initial depth jump", lines: []string{"root", "\t\tgrandchild"}},
		{name: "later depth jump", lines: []string{"root", "\tchild", "\t\t\ttoo-deep"}},
		{name: "second root", lines: []string{"root", "other-root"}},
		{name: "empty child name", lines: []string{"root", "\t"}},
		{name: "tabs only root", lines: []string{"\t\t"}},
	}

	for _, test := range tests {
		t.Run(test.name, func(t *testing.T) {
			original := append([]string(nil), test.lines...)
			root, err := parseWithoutPanic(t, test.lines)
			if err == nil {
				t.Fatalf("ParseOutline(%#v) returned nil error", test.lines)
			}
			if root != nil {
				t.Fatalf("ParseOutline(%#v) root = %#v, want nil", test.lines, root)
			}
			if !reflect.DeepEqual(test.lines, original) {
				t.Fatalf("ParseOutline modified malformed input: got %#v, want %#v", test.lines, original)
			}
		})
	}
}

