import "sort"

func RankRowSums(matrix [][]int64) []int {
	sums := make([]int64, len(matrix))
	rows := make([]int, len(matrix))
	for i, row := range matrix {
		rows[i] = i
		for _, value := range row {
			sums[i] += value
		}
	}

	sort.SliceStable(rows, func(i, j int) bool {
		return sums[rows[i]] > sums[rows[j]]
	})
	return rows
}

