package solution

import (
	"reflect"
	"testing"
)

func TestParseBadgeManifestValidRecords(t *testing.T) {
	text := "\nAlpha+Beta|0|plus+stays\nPipe%7CName|100|snowman%20%E2%98%83\nCaf%C3%A9|42|\n\n"
	want := []Badge{
		{Name: "Alpha+Beta", Rank: 0, Note: "plus+stays"},
		{Name: "Pipe|Name", Rank: 100, Note: "snowman ☃"},
		{Name: "Café", Rank: 42, Note: ""},
	}

	got, err := ParseBadgeManifest(text)
	if err != nil {
		t.Fatalf("ParseBadgeManifest returned unexpected error: %v", err)
	}
	if !reflect.DeepEqual(got, want) {
		t.Fatalf("ParseBadgeManifest() = %#v, want %#v", got, want)
	}
}

func TestParseBadgeManifestEmptyIsNonNil(t *testing.T) {
	for _, text := range []string{"", "\n", "\n\n\n"} {
		got, err := ParseBadgeManifest(text)
		if err != nil {
			t.Fatalf("ParseBadgeManifest(%q) returned error: %v", text, err)
		}
		if got == nil {
			t.Fatalf("ParseBadgeManifest(%q) returned a nil slice", text)
		}
		if len(got) != 0 {
			t.Fatalf("ParseBadgeManifest(%q) returned %#v, want empty slice", text, got)
		}
	}
}

func TestParseBadgeManifestRejectsMalformedInputWithoutPartialResult(t *testing.T) {
	tests := []struct {
		name string
		text string
	}{
		{name: "too few fields", text: "name|1"},
		{name: "too many fields", text: "name|1|note|extra"},
		{name: "bad name escape short", text: "bad%2|1|note"},
		{name: "bad note escape hex", text: "name|1|%GG"},
		{name: "invalid utf8 name", text: "%FF|1|note"},
		{name: "invalid utf8 note", text: "name|1|%C3%28"},
		{name: "empty name", text: "|1|note"},
		{name: "decoded empty name", text: "|0|"},
		{name: "empty rank", text: "name||note"},
		{name: "negative rank", text: "name|-1|note"},
		{name: "explicit plus rank", text: "name|+1|note"},
		{name: "space in rank", text: "name| 1|note"},
		{name: "non ascii digit", text: "name|１|note"},
		{name: "rank above range", text: "name|101|note"},
		{name: "rank overflow", text: "name|999999999999999999999999999999999999|note"},
		{name: "error after valid record", text: "good|1|ok\nbad|2"},
	}

	for _, tc := range tests {
		t.Run(tc.name, func(t *testing.T) {
			got, err := ParseBadgeManifest(tc.text)
			if err == nil {
				t.Fatalf("ParseBadgeManifest(%q) returned no error; result %#v", tc.text, got)
			}
			if len(got) != 0 {
				t.Fatalf("ParseBadgeManifest(%q) returned partial result %#v", tc.text, got)
			}
		})
	}
}

func TestParseBadgeManifestRankBoundariesAndLeadingZeroes(t *testing.T) {
	got, err := ParseBadgeManifest("zero|000|a\nhundred|100|b")
	if err != nil {
		t.Fatalf("ParseBadgeManifest returned unexpected error: %v", err)
	}
	want := []Badge{{Name: "zero", Rank: 0, Note: "a"}, {Name: "hundred", Rank: 100, Note: "b"}}
	if !reflect.DeepEqual(got, want) {
		t.Fatalf("ParseBadgeManifest() = %#v, want %#v", got, want)
	}
}

