package solution

import (
	"reflect"
	"testing"
)

func TestDecodeCatalogValid(t *testing.T) {
	tests := []struct {
		name string
		text string
		want Catalog
	}{
		{
			name: "single entry",
			text: "unit=USD\nITEM-1,250",
			want: Catalog{Unit: "USD", Entries: []CatalogEntry{{Code: "ITEM-1", Price: 250}}},
		},
		{
			name: "preserves entry order",
			text: "unit=EUR\nZ9,7\nA-2,19\nM,0",
			want: Catalog{Unit: "EUR", Entries: []CatalogEntry{
				{Code: "Z9", Price: 7},
				{Code: "A-2", Price: 19},
				{Code: "M", Price: 0},
			}},
		},
		{
			name: "maximum price",
			text: "unit=JPY\nMAX,18446744073709551615",
			want: Catalog{Unit: "JPY", Entries: []CatalogEntry{{Code: "MAX", Price: ^uint64(0)}}},
		},
		{
			name: "leading zeroes and minimal valid code",
			text: "unit=GBP\n-,00001\n9,00",
			want: Catalog{Unit: "GBP", Entries: []CatalogEntry{
				{Code: "-", Price: 1},
				{Code: "9", Price: 0},
			}},
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			got, err := DecodeCatalog(tt.text)
			if err != nil {
				t.Fatalf("DecodeCatalog returned error: %v", err)
			}
			if !reflect.DeepEqual(got, tt.want) {
				t.Fatalf("DecodeCatalog() = %#v, want %#v", got, tt.want)
			}
		})
	}
}

func TestDecodeCatalogRejectsMalformedInput(t *testing.T) {
	tests := []struct {
		name string
		text string
	}{
		{"empty input", ""},
		{"missing entries", "unit=USD"},
		{"empty unit", "unit=\nA,1"},
		{"short unit", "unit=US\nA,1"},
		{"long unit", "unit=USDX\nA,1"},
		{"lowercase unit", "unit=Usd\nA,1"},
		{"digit in unit", "unit=US1\nA,1"},
		{"wrong header key", "currency=USD\nA,1"},
		{"extra header separator", "unit=USD=X\nA,1"},
		{"leading space", " unit=USD\nA,1"},
		{"carriage return", "unit=USD\r\nA,1"},
		{"trailing newline", "unit=USD\nA,1\n"},
		{"blank entry line", "unit=USD\nA,1\n\nB,2"},
		{"empty code", "unit=USD\n,1"},
		{"lowercase code", "unit=USD\nAb,1"},
		{"underscore in code", "unit=USD\nA_B,1"},
		{"space in code", "unit=USD\nA B,1"},
		{"non ASCII code", "unit=USD\nCAFÉ,1"},
		{"missing comma", "unit=USD\nA1"},
		{"extra comma", "unit=USD\nA,1,2"},
		{"empty price", "unit=USD\nA,"},
		{"negative price", "unit=USD\nA,-1"},
		{"positive sign", "unit=USD\nA,+1"},
		{"space in price", "unit=USD\nA, 1"},
		{"non ASCII digit", "unit=USD\nA,١"},
		{"price overflow", "unit=USD\nA,18446744073709551616"},
		{"duplicate code", "unit=USD\nA,1\nA,2"},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			if _, err := DecodeCatalog(tt.text); err == nil {
				t.Fatalf("DecodeCatalog(%q) returned nil error", tt.text)
			}
		})
	}
}

