package solution

func RotateRows(rows [][]int, shift int) [][]int {
	rotated := make([][]int, len(rows))
	for i, row := range rows {
		if len(row) == 0 {
			rotated[i] = make([]int, 0)
			continue
		}

		amount := shift % len(row)
		if amount < 0 {
			amount += len(row)
		}
		out := make([]int, len(row))
		copy(out, row[amount:])
		copy(out[len(row)-amount:], row[:amount])
		rotated[i] = out
	}
	return rotated
}

