import (
	"bytes"
	"testing"
)

func requireJournalSnapshot(t *testing.T, journal *Journal, want [][]byte) {
	t.Helper()
	got := journal.Snapshot()
	if len(got) != len(want) {
		t.Fatalf("Snapshot length = %d, want %d; snapshot=%q", len(got), len(want), got)
	}
	for i := range want {
		if !bytes.Equal(got[i], want[i]) {
			t.Fatalf("Snapshot record %d = %v, want %v", i, got[i], want[i])
		}
	}
}

func TestJournalZeroValueAppendMarkAndRollback(t *testing.T) {
	var journal Journal
	if mark := journal.Mark(); mark != 0 {
		t.Fatalf("initial Mark() = %d, want 0", mark)
	}

	journal.Append([]byte("first"))
	mark := journal.Mark()
	if mark != 1 {
		t.Fatalf("Mark() after one append = %d, want 1", mark)
	}
	journal.Append([]byte("second"))
	journal.Append([]byte("third"))
	requireJournalSnapshot(t, &journal, [][]byte{[]byte("first"), []byte("second"), []byte("third")})

	journal.Rollback(mark)
	requireJournalSnapshot(t, &journal, [][]byte{[]byte("first")})
	if got := journal.Mark(); got != 1 {
		t.Fatalf("Mark() after rollback = %d, want 1", got)
	}

	journal.Append([]byte("replacement"))
	requireJournalSnapshot(t, &journal, [][]byte{[]byte("first"), []byte("replacement")})
}

func TestJournalRollbackToEmptyAndCurrentMark(t *testing.T) {
	var journal Journal
	emptyMark := journal.Mark()
	journal.Append([]byte{1})
	journal.Append([]byte{2})
	journal.Rollback(emptyMark)
	requireJournalSnapshot(t, &journal, nil)

	journal.Append([]byte{3})
	current := journal.Mark()
	journal.Rollback(current)
	requireJournalSnapshot(t, &journal, [][]byte{[]byte{3}})
}

