	journal.Append(record)
	record[0] = 99
	record = append(record, 4)
	requireJournalSnapshot(t, &journal, [][]byte{[]byte{1, 2, 3}})

	empty := []byte{}
	journal.Append(empty)
	requireJournalSnapshot(t, &journal, [][]byte{[]byte{1, 2, 3}, []byte{}})
}

