package solution

import "testing"

func TestCounterAppliesStepsAndReportsValue(t *testing.T) {
	c := NewCounter(10)

	got, err := c.Apply("tx-1", " +5; -3 ;+10 ")
	if err != nil {
		t.Fatalf("Apply returned unexpected error: %v", err)
	}
	if got != 22 {
		t.Fatalf("Apply result = %d, want 22", got)
	}
	if gotValue := c.Value(); gotValue != 22 {
		t.Fatalf("Value() = %d, want 22", gotValue)
	}
}

func TestCounterCompletedTransactionIsIdempotent(t *testing.T) {
	c := NewCounter(4)

	first, err := c.Apply("same", "+6;-2")
	if err != nil {
		t.Fatalf("first Apply returned error: %v", err)
	}
	second, err := c.Apply("same", "+1000")
	if err != nil {
		t.Fatalf("reused Apply returned error: %v", err)
	}
	if first != 8 || second != 8 {
		t.Fatalf("results = (%d, %d), want (8, 8)", first, second)
	}
	if got := c.Value(); got != 8 {
		t.Fatalf("Value() after transaction reuse = %d, want 8", got)
	}
}

func TestCounterMalformedTransactionIsAtomicAndRetryable(t *testing.T) {
	c := NewCounter(20)

	got, err := c.Apply("retryable", "+7;broken;-2")
	if err == nil {
		t.Fatal("malformed transaction returned nil error")
	}
	if got != 20 {
		t.Fatalf("malformed transaction result = %d, want pre-call value 20", got)
	}
	if value := c.Value(); value != 20 {
		t.Fatalf("malformed transaction changed counter to %d, want 20", value)
	}

	got, err = c.Apply("retryable", "+3")
	if err != nil {
		t.Fatalf("retry with same transaction ID returned error: %v", err)
	}
	if got != 23 || c.Value() != 23 {
		t.Fatalf("retry result/value = %d/%d, want 23/23", got, c.Value())
	}
}

func TestCounterRejectsAllMalformedStepFormsWithoutMutation(t *testing.T) {
	malformed := []string{
		"",
		"   ",
		"+",
		"-",
		"1",
		"++1",
		"+-1",
		"+ 1",
		"+1x",
		"+١",
		"+1;",
		";+1",
		"+1;;+2",
	}

	for i, script := range malformed {
		c := NewCounter(9)
		tx := "bad"
		got, err := c.Apply(tx, script)
		if err == nil {
			t.Errorf("case %d, script %q: expected error", i, script)
			continue
		}
		if got != 9 || c.Value() != 9 {
			t.Errorf("case %d, script %q: result/value = %d/%d, want 9/9", i, script, got, c.Value())
			continue
		}

		got, err = c.Apply(tx, "+1")
		if err != nil {
			t.Errorf("case %d, script %q: transaction ID was not retryable: %v", i, script, err)
			continue
		}
		if got != 10 || c.Value() != 10 {
			t.Errorf("case %d, script %q: retry result/value = %d/%d, want 10/10", i, script, got, c.Value())
		}
	}
}

func TestCounterAllowsEmptyTransactionID(t *testing.T) {
	c := NewCounter(-2)

	got, err := c.Apply("", "+2")
	if err != nil {
		t.Fatalf("Apply with empty transaction ID returned error: %v", err)
	}
	if got != 0 {
		t.Fatalf("first result = %d, want 0", got)
	}

	got, err = c.Apply("", "-50")
	if err != nil {
		t.Fatalf("reusing empty transaction ID returned error: %v", err)
	}
	if got != 0 || c.Value() != 0 {
		t.Fatalf("reused result/value = %d/%d, want 0/0", got, c.Value())
	}
}

