func TestRunePrefixesAddsCompleteCodePoints(t *testing.T) {
	text := "猫aé🙂"
	want := []string{"猫", "猫a", "猫aé", "猫aé🙂"}

	got := RunePrefixes(text)
	if !reflect.DeepEqual(got, want) {
		t.Fatalf("RunePrefixes(%q) = %#v, want %#v", text, got, want)
	}
	for i, prefix := range got {
		if !utf8.ValidString(prefix) {
			t.Errorf("prefix %d, %q, is not valid UTF-8", i, prefix)
		}
	}
}

func TestRunePrefixesASCII(t *testing.T) {
	want := []string{"a", "ab", "abc"}
	got := RunePrefixes("abc")
	if !reflect.DeepEqual(got, want) {
		t.Fatalf("RunePrefixes(abc) = %#v, want %#v", got, want)
	}
}

func TestRunePrefixesEmptyReturnsNonNilEmptySlice(t *testing.T) {
	got := RunePrefixes("")
	if got == nil {
		t.Fatal("RunePrefixes(empty) returned nil, want non-nil empty slice")
	}
	if len(got) != 0 {
		t.Fatalf("RunePrefixes(empty) = %#v, want empty slice", got)
	}
}

func TestRunePrefixesCallsAreIsolated(t *testing.T) {
	first := RunePrefixes("xy")
	if !reflect.DeepEqual(first, []string{"x", "xy"}) {
		t.Fatalf("first call = %#v", first)
	}

	empty := RunePrefixes("")
	if empty == nil || len(empty) != 0 {
		t.Fatalf("empty call after non-empty call = %#v, want non-nil empty slice", empty)
	}

