            Solution.countByOwner(new String[] {
                "FB:x", "Ea:y", "Aa:z", "BB:q", "Ea:r", "FB:s"
            }), "order must remain stable even for hash-colliding names");

        assertListEquals(Arrays.asList("owner=3", "other=1"),
            Solution.countByOwner(new String[] {
                "owner:", "owner:a:b", "other:value", "owner:last"
            }), "assignment contents must not affect owner extraction");

