import java.util.Arrays;

public class SolutionTest {
    public static void main(String[] args) {
        int[] emptyFirst = Solution.decodeReadings(new byte[0]);
        int[] emptySecond = Solution.decodeReadings(new byte[0]);
        assertIntArrayEquals(new int[0], emptyFirst, "empty input");
        if (emptyFirst == emptySecond) {
            throw new AssertionError("each empty invocation must return a fresh array");
        }

        byte[] packed = {
            (byte) 0x00, (byte) 0x00,
            (byte) 0x3F, (byte) 0xFF,
            (byte) 0xA0, (byte) 0x01,
            (byte) 0xFF, (byte) 0xFF
        };
        byte[] snapshot = packed.clone();
        int[] decoded = Solution.decodeReadings(packed);
        assertIntArrayEquals(new int[] {
            0, 0,
            1, 8191,
            5, 1,
            7, 8191
        }, decoded, "boundary IDs and readings");
        assertByteArrayEquals(snapshot, packed, "input must not be modified");

        assertIntArrayEquals(new int[] {
            0, 255,
            3, 256,
            6, 4266
        }, Solution.decodeReadings(new byte[] {
            (byte) 0x00, (byte) 0xFF,
            (byte) 0x61, (byte) 0x00,
            (byte) 0xD0, (byte) 0xAA
        }), "bytes must be interpreted as unsigned bit patterns");

        byte[] isolatedInput = {(byte) 0x21, (byte) 0x23};
        int[] first = Solution.decodeReadings(isolatedInput);
        int[] second = Solution.decodeReadings(isolatedInput);
        if (first == second) {
            throw new AssertionError("each invocation must return a fresh result array");
        }
        assertIntArrayEquals(new int[] {1, 291}, first, "initial isolated result");
        assertIntArrayEquals(new int[] {1, 291}, second, "second isolated result");

        first[0] = 99;
        first[1] = 99;
        assertIntArrayEquals(new int[] {1, 291}, second,
            "mutating one result must not affect another result");

        isolatedInput[0] = (byte) 0xFF;
        isolatedInput[1] = (byte) 0xFF;
        assertIntArrayEquals(new int[] {1, 291}, second,
            "mutating the input after return must not affect an existing result");
        assertIntArrayEquals(new int[] {7, 8191}, Solution.decodeReadings(isolatedInput),
            "a later call must decode the input's current contents independently");
    }

    private static void assertIntArrayEquals(int[] expected, int[] actual, String message) {
        if (actual == null || !Arrays.equals(expected, actual)) {
            throw new AssertionError(message + ": expected " + Arrays.toString(expected)
                + " but got " + Arrays.toString(actual));
        }
    }

    private static void assertByteArrayEquals(byte[] expected, byte[] actual, String message) {
        if (!Arrays.equals(expected, actual)) {
            throw new AssertionError(message + ": expected " + Arrays.toString(expected)
