import java.util.Arrays;

public final class Solution {
    private Solution() {
    }

    public interface Acknowledgement {
        void complete();
    }

    public interface Handler {
        void onMessage(byte[] message, Acknowledgement acknowledgement);
    }

    public static boolean[] dispatch(byte[][] messages, Handler handler) {
        boolean[] acknowledged = new boolean[messages.length];

        for (int i = 0; i < messages.length; i++) {
            byte[] snapshot = Arrays.copyOf(messages[i], messages[i].length);
            final boolean[] completed = {false};
            Acknowledgement acknowledgement = () -> completed[0] = true;

            handler.onMessage(snapshot, acknowledgement);
            acknowledged[i] = completed[0];
        }

        return acknowledged;
    }
}

