import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;

public class SolutionTest {
    public static void main(String[] args) {
        testValidMalformedAndCallbackOrder();
        testSeparatorBoundaries();
        testEmptyInput();
    }

    private static void testValidMalformedAndCallbackOrder() {
        String[] records = {"a=1", "b=", "c=x=y", null, "missing", "=bad"};
        String[] original = records.clone();
        List<String> events = new ArrayList<>();

        Solution.replay(records, new Solution.EntryListener() {
            public void onEntry(String key, String value) {
                events.add("E:" + key + ":" + value);
            }

            public void onMalformed(int index, String record) {
                events.add("M:" + index + ":" + String.valueOf(record));
            }
        }, (valid, malformed) -> events.add("C:" + valid + ":" + malformed));

        assertEquals(Arrays.asList(
                "E:a:1",
                "E:b:",
                "E:c:x=y",
                "M:3:null",
                "M:4:missing",
                "M:5:=bad",
                "C:3:3"), events, "mixed records");
        assertTrue(Arrays.equals(original, records), "input array was mutated");
    }

    private static void testSeparatorBoundaries() {
        List<String> events = new ArrayList<>();
        Solution.replay(new String[]{"=", "k==", " =value", "key=value="},
                listener(events),
                (valid, malformed) -> events.add("C:" + valid + ":" + malformed));

        assertEquals(Arrays.asList(
                "M:0:=",
                "E:k:=",
                "E: :value",
                "E:key:value=",
                "C:3:1"), events, "separator boundaries");
    }

    private static void testEmptyInput() {
        List<String> events = new ArrayList<>();
        Solution.replay(new String[0], listener(events),
                (valid, malformed) -> events.add("C:" + valid + ":" + malformed));

        assertEquals(Arrays.asList("C:0:0"), events, "empty input");
    }

    private static Solution.EntryListener listener(List<String> events) {
        return new Solution.EntryListener() {
            public void onEntry(String key, String value) {
                events.add("E:" + key + ":" + value);
            }

            public void onMalformed(int index, String record) {
                events.add("M:" + index + ":" + String.valueOf(record));
            }
        };
    }

    private static void assertEquals(Object expected, Object actual, String context) {
        if (!expected.equals(actual)) {
            throw new AssertionError(context + " expected " + expected + " but got " + actual);
        }
    }

    private static void assertTrue(boolean condition, String message) {
        if (!condition) {
            throw new AssertionError(message);
        }
    }
}

