import java.util.ArrayList;
import java.util.Arrays;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

public class SolutionTest {
    public static void main(String[] args) {
        testDepthFirstDependencyOrder();
        testStableAcrossMapAndListOrders();
        testRootWithoutDependencies();
    }

    private static void testDepthFirstDependencyOrder() {
        Map<String, List<String>> graph = firstGraph();
        Map<String, List<String>> snapshot = deepCopy(graph);

        List<String> actual = Solution.dependencyOrder(graph, "root");
        List<String> expected = Arrays.asList("c", "d", "a", "b", "m", "z", "root");

        assertEquals(expected, actual, "depth-first order");
        assertEquals(snapshot, graph, "input graph mutation");
        assertTrue(!actual.contains("unused"), "unreachable component was included");
    }

    private static void testStableAcrossMapAndListOrders() {
        List<String> first = Solution.dependencyOrder(firstGraph(), "root");

        Map<String, List<String>> reordered = new LinkedHashMap<>();
        reordered.put("unused", list());
        reordered.put("z", list("c"));
        reordered.put("m", list("d", "b"));
        reordered.put("root", list("m", "a", "z"));
        reordered.put("d", list());
        reordered.put("c", list());
        reordered.put("b", list());
        reordered.put("a", list("c", "d"));

        List<String> second = Solution.dependencyOrder(reordered, "root");
        assertEquals(first, second, "ordering stability");
    }

    private static void testRootWithoutDependencies() {
        Map<String, List<String>> graph = new LinkedHashMap<>();
        graph.put("solo", list());
        graph.put("other", list());

        assertEquals(Arrays.asList("solo"), Solution.dependencyOrder(graph, "solo"),
                "root-only graph");
    }

    private static Map<String, List<String>> firstGraph() {
        Map<String, List<String>> graph = new LinkedHashMap<>();
        graph.put("root", list("z", "a", "m"));
        graph.put("a", list("d", "c"));
        graph.put("m", list("d", "b"));
        graph.put("z", list("c"));
        graph.put("b", list());
        graph.put("c", list());
        graph.put("d", list());
        graph.put("unused", list());
        return graph;
    }

    private static List<String> list(String... values) {
        return new ArrayList<>(Arrays.asList(values));
    }

    private static Map<String, List<String>> deepCopy(Map<String, List<String>> source) {
        Map<String, List<String>> copy = new LinkedHashMap<>();
        for (Map.Entry<String, List<String>> entry : source.entrySet()) {
            copy.put(entry.getKey(), new ArrayList<>(entry.getValue()));
        }
        return copy;
    }

    private static void assertEquals(Object expected, Object actual, String context) {
        if (!expected.equals(actual)) {
            throw new AssertionError(context + " expected " + expected + " but got " + actual);
        }
    }

    private static void assertTrue(boolean condition, String message) {
        if (!condition) {
            throw new AssertionError(message);
        }
    }
}

