import java.util.ArrayList;
import java.util.Arrays;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;

public class SolutionTest {
    public static void main(String[] args) {
        testCycleAndBranching();
        testRepeatedCallsAreIsolated();
        testDifferentGraphsAreIsolated();
        testNodeWithNoOutgoingEdges();
    }

    private static void testCycleAndBranching() {
        Map<String, List<String>> graph = cyclicGraph();
        Map<String, List<String>> snapshot = deepCopy(graph);

        Set<String> actual = Solution.reachable(graph, "a");
        assertEquals(set("a", "b", "c", "d"), actual, "cyclic reachability");
        assertEquals(snapshot, graph, "input graph mutation");
        assertTrue(!actual.contains("isolated"), "unreachable node was included");
    }

    private static void testRepeatedCallsAreIsolated() {
        Map<String, List<String>> graph = cyclicGraph();

        assertEquals(set("a", "b", "c", "d"), Solution.reachable(graph, "a"),
                "first invocation");
        assertEquals(set("isolated"), Solution.reachable(graph, "isolated"),
                "second invocation leaked traversal state");
        assertEquals(set("c", "a", "b", "d"), Solution.reachable(graph, "c"),
                "third invocation after a different start");
    }

    private static void testDifferentGraphsAreIsolated() {
        Map<String, List<String>> first = cyclicGraph();
        Solution.reachable(first, "a");

        Map<String, List<String>> second = new LinkedHashMap<>();
        second.put("x", list("y"));
        second.put("y", list());

        assertEquals(set("x", "y"), Solution.reachable(second, "x"),
                "state leaked between graphs");
    }

    private static void testNodeWithNoOutgoingEdges() {
        Map<String, List<String>> graph = new LinkedHashMap<>();
        graph.put("solo", list());

        assertEquals(set("solo"), Solution.reachable(graph, "solo"),
                "zero-edge reachability");
    }

    private static Map<String, List<String>> cyclicGraph() {
        Map<String, List<String>> graph = new LinkedHashMap<>();
        graph.put("a", list("b", "d"));
        graph.put("b", list("c"));
        graph.put("c", list("a"));
        graph.put("d", list("d"));
        graph.put("isolated", list());
        return graph;
    }

    private static List<String> list(String... values) {
        return new ArrayList<>(Arrays.asList(values));
    }

    private static Set<String> set(String... values) {
        return new HashSet<>(Arrays.asList(values));
    }

    private static Map<String, List<String>> deepCopy(Map<String, List<String>> source) {
        Map<String, List<String>> copy = new LinkedHashMap<>();
        for (Map.Entry<String, List<String>> entry : source.entrySet()) {
            copy.put(entry.getKey(), new ArrayList<>(entry.getValue()));
        }
        return copy;
    }

    private static void assertEquals(Object expected, Object actual, String context) {
        if (!expected.equals(actual)) {
            throw new AssertionError(context + " expected " + expected + " but got " + actual);
        }
    }

    private static void assertTrue(boolean condition, String message) {
        if (!condition) {
            throw new AssertionError(message);
        }
    }
}

