        testDistinctValuesAndDuplicates();
        testZeroLimitAndEmptyInput();
        testLongAccumulation();
        testNonMutationAndRepeatedCalls();
    }

    private static void testDistinctValuesAndDuplicates() {
        assertEquals(23L,
                Solution.totalUniqueCredits(new int[]{12, 4, 12, 9}, 10),
                "duplicate values must contribute once");
        assertEquals(12L,
                Solution.totalUniqueCredits(new int[]{3, 3, 4, 5, 4}, 100),
                "limit above every value");
    }

    private static void testZeroLimitAndEmptyInput() {
        assertEquals(0L,
                Solution.totalUniqueCredits(new int[]{0, 1, Integer.MAX_VALUE, 1}, 0),
                "zero per-value limit");
        assertEquals(0L,
                Solution.totalUniqueCredits(new int[0], Integer.MAX_VALUE),
                "empty input");
    }

    private static void testLongAccumulation() {
        int[] credits = {Integer.MAX_VALUE, Integer.MAX_VALUE - 1, Integer.MAX_VALUE - 2};
        assertEquals(6_442_450_938L,
                Solution.totalUniqueCredits(credits, Integer.MAX_VALUE),
                "total must use long arithmetic");
    }

    private static void testNonMutationAndRepeatedCalls() {
        int[] credits = {8, 2, 8, 20};
        int[] original = credits.clone();

        assertEquals(15L, Solution.totalUniqueCredits(credits, 5), "first call");
        if (!Arrays.equals(original, credits)) {
            throw new AssertionError("input array was modified: " + Arrays.toString(credits));
        }

        assertEquals(1L,
                Solution.totalUniqueCredits(new int[]{1, 1, 1}, 10),
                "later call must be independent");
        assertEquals(15L,
                Solution.totalUniqueCredits(credits, 5),
                "repeated call must remain stable");
    }

    private static void assertEquals(long expected, long actual, String message) {
        if (expected != actual) {
            throw new AssertionError(message + ": expected " + expected + " but got " + actual);
        }
