import java.util.Arrays;

public class SolutionTest {
    public static void main(String[] args) {
        testDuplicateIdsAndFlooring();
        testLargeAccumulatedValues();
        testBoundaryPercentages();
        testNonMutationAndInvocationStability();
    }

    private static void testDuplicateIdsAndFlooring() {
        String[] ids = {new String("A"), "B", new String("A"), "C"};
        int[] completed = {1, 8, 100, 0};
        int[] total = {3, 10, 100, 7};

        assertEquals(45, Solution.completionPercent(ids, completed, total),
                "only the first equal activity ID must contribute");
    }

    private static void testLargeAccumulatedValues() {
        String[] ids = {"large-1", "large-2", "large-3"};
        int[] completed = {1_000_000_000, 1_000_000_000, 0};
        int[] total = {1_000_000_000, 1_000_000_000, 1_000_000_000};

        assertEquals(66, Solution.completionPercent(ids, completed, total),
                "sums and multiplication must not overflow int");
    }

    private static void testBoundaryPercentages() {
        assertEquals(0,
                Solution.completionPercent(new String[]{"none"}, new int[]{0}, new int[]{1}),
                "zero percent");
        assertEquals(100,
                Solution.completionPercent(new String[]{"done"}, new int[]{1_000_000_000},
                        new int[]{1_000_000_000}),
                "one hundred percent");
        assertEquals(66,
                Solution.completionPercent(new String[]{"fraction"}, new int[]{2}, new int[]{3}),
                "fractional percentage must be floored");
    }

    private static void testNonMutationAndInvocationStability() {
        String[] ids = {"x", "y", "x"};
        int[] completed = {5, 1, 0};
        int[] total = {10, 2, 1};
        String[] originalIds = ids.clone();
        int[] originalCompleted = completed.clone();
        int[] originalTotal = total.clone();

        assertEquals(50, Solution.completionPercent(ids, completed, total), "initial call");
        assertEquals(0,
                Solution.completionPercent(new String[]{"other"}, new int[]{0}, new int[]{9}),
                "independent later call");
        assertEquals(50, Solution.completionPercent(ids, completed, total), "repeated call");

        if (!Arrays.equals(originalIds, ids)) {
            throw new AssertionError("activityIds was modified");
        }
        if (!Arrays.equals(originalCompleted, completed)) {
            throw new AssertionError("completedUnits was modified");
        }
        if (!Arrays.equals(originalTotal, total)) {
            throw new AssertionError("totalUnits was modified");
        }
    }

    private static void assertEquals(int expected, int actual, String message) {
        if (expected != actual) {
            throw new AssertionError(message + ": expected " + expected + " but got " + actual);
        }
    }
}

