public class SolutionTest {
    public static void main(String[] args) {
        testSortingAndNonMutation();
        testExtremeCoordinates();
        testEmptyAndSingleElementInputs();
        testReturnedArrayDoesNotAliasInput();
    }

    private static void testSortingAndNonMutation() {
        int[] positions = {10, -3, 4, 10, 1};
        int[] original = positions.clone();

        int[] actual = Solution.sortedDistances(positions, 2);

        assertArrayEquals(new int[]{1, 2, 5, 8, 8}, actual, "sorted distances");
        assertArrayEquals(original, positions, "positions array was modified");
        if (actual == positions) {
            throw new AssertionError("returned array aliases positions");
        }
    }

    private static void testExtremeCoordinates() {
        int[] positions = {Integer.MIN_VALUE, -1, Integer.MAX_VALUE - 1};
        assertArrayEquals(
                new int[]{0, Integer.MAX_VALUE, Integer.MAX_VALUE},
                Solution.sortedDistances(positions, -1),
                "distance calculation must use long subtraction");
    }

    private static void testEmptyAndSingleElementInputs() {
        int[] empty = new int[0];
        int[] emptyResult = Solution.sortedDistances(empty, 123);
        assertArrayEquals(new int[0], emptyResult, "empty input");
        if (emptyResult == empty) {
            throw new AssertionError("empty result aliases empty input");
        }

        assertArrayEquals(new int[]{0},
                Solution.sortedDistances(new int[]{Integer.MAX_VALUE}, Integer.MAX_VALUE),
                "coordinate at origin");
    }

    private static void testReturnedArrayDoesNotAliasInput() {
        int[] positions = {7, 9};
        int[] result = Solution.sortedDistances(positions, 8);
        result[0] = 99;
        assertArrayEquals(new int[]{7, 9}, positions,
                "mutating the result must not affect the input");
    }

    private static void assertArrayEquals(int[] expected, int[] actual, String message) {
        if (!Arrays.equals(expected, actual)) {
            throw new AssertionError(message + ": expected " + Arrays.toString(expected)
                    + " but got " + Arrays.toString(actual));
        }
    }
}

