import java.util.Arrays;

public class SolutionTest {
    public static void main(String[] args) {
        testNormalAndNegativeDeltas();
        testLongAccumulation();
        testFreshAllocationAndRetainedResultStability();
        testEmptyInputAndNonMutation();
    }

    private static void testNormalAndNegativeDeltas() {
        int[] deltas = {5, -2, 7, -10, 1};
        int[] original = deltas.clone();

        assertArrayEquals(new long[]{5L, 3L, 10L, 0L, 1L},
                Solution.prefixTotals(deltas), "mixed deltas");
        assertIntArrayEquals(original, deltas, "input array was modified");
    }

    private static void testLongAccumulation() {
        int[] deltas = {Integer.MAX_VALUE, Integer.MAX_VALUE, Integer.MIN_VALUE};
        assertArrayEquals(
                new long[]{2_147_483_647L, 4_294_967_294L, 2_147_483_646L},
                Solution.prefixTotals(deltas),
                "prefixes must use long arithmetic");
    }

    private static void testFreshAllocationAndRetainedResultStability() {
        int[] deltas = {1, 2, 3};
        long[] first = Solution.prefixTotals(deltas);
        long[] snapshot = first.clone();
        long[] second = Solution.prefixTotals(new int[]{9, 9, 9});

        if (first == second) {
            throw new AssertionError("separate invocations returned the same array");
        }
        assertArrayEquals(snapshot, first, "later invocation changed an earlier result");
        assertArrayEquals(new long[]{9L, 18L, 27L}, second, "later invocation result");

        second[0] = -100L;
        assertArrayEquals(snapshot, first, "results from different calls alias each other");

        long[] third = Solution.prefixTotals(deltas);
        if (third == first) {
            throw new AssertionError("repeated invocation did not allocate a new result");
        }
        assertArrayEquals(snapshot, third, "repeated invocation result");
    }

    private static void testEmptyInputAndNonMutation() {
        int[] empty = new int[0];
        long[] first = Solution.prefixTotals(empty);
        long[] second = Solution.prefixTotals(empty);

        assertArrayEquals(new long[0], first, "empty input result");
        if (first == second) {
            throw new AssertionError("empty invocations must also return newly allocated arrays");
        }
        if (empty.length != 0) {
            throw new AssertionError("empty input was modified");
        }
    }

    private static void assertArrayEquals(long[] expected, long[] actual, String message) {
        if (!Arrays.equals(expected, actual)) {
            throw new AssertionError(message + ": expected " + Arrays.toString(expected)
                    + " but got " + Arrays.toString(actual));
        }
    }

    private static void assertIntArrayEquals(int[] expected, int[] actual, String message) {
        if (!Arrays.equals(expected, actual)) {
            throw new AssertionError(message + ": expected " + Arrays.toString(expected)
                    + " but got " + Arrays.toString(actual));
        }
    }
}

