import java.util.Arrays;
import java.util.List;

public class SolutionTest {
    public static void main(String[] args) {
        testOrderingAndBoundaries();
        testEmptyAndNonMutation();
        testStableIdenticalRecords();
        testMalformedInputs();
    }

    private static void testOrderingAndBoundaries() {
        String[] requests = {
            "zeta|9|2",
            "beta|9|1",
            "Alpha|9|1",
            "low|0|0",
            "max_seq|5|9223372036854775807",
            "first|5|0"
        };
        assertListEquals(
            Arrays.asList(
                "Alpha|9|1",
                "beta|9|1",
                "zeta|9|2",
                "first|5|0",
                "max_seq|5|9223372036854775807",
                "low|0|0"
            ),
            Solution.prioritize(requests)
        );
    }

    private static void testEmptyAndNonMutation() {
        String[] empty = new String[0];
        assertListEquals(Arrays.asList(), Solution.prioritize(empty));

        String[] requests = {"b|1|2", "a|9|3", "c|1|1"};
        String[] snapshot = requests.clone();
        Solution.prioritize(requests);
        if (!Arrays.equals(snapshot, requests)) {
            throw new AssertionError("input array was modified");
        }
    }

    private static void testStableIdenticalRecords() {
        String first = new String("same|4|7");
        String second = new String("same|4|7");
        String[] requests = {first, "top|9|0", second};
        List<String> result = Solution.prioritize(requests);
        assertListEquals(Arrays.asList("top|9|0", "same|4|7", "same|4|7"), result);
        if (result.get(1) != first || result.get(2) != second) {
            throw new AssertionError("identical records were not retained stably");
        }
    }

    private static void testMalformedInputs() {
        expectIllegalArgument("requests must not be null", () -> Solution.prioritize(null));
        expectIllegalArgument("invalid request at index 1", () ->
            Solution.prioritize(new String[]{"ok|1|0", null}));
        expectIllegalArgument("invalid request at index 0", () ->
            Solution.prioritize(new String[]{"name|1"}));
        expectIllegalArgument("invalid request at index 0", () ->
            Solution.prioritize(new String[]{"name|1|2|extra"}));
        expectIllegalArgument("invalid request at index 0", () ->
            Solution.prioritize(new String[]{"1name|1|2"}));
        expectIllegalArgument("invalid request at index 0", () ->
            Solution.prioritize(new String[]{"bad-name|1|2"}));
        expectIllegalArgument("invalid request at index 0", () ->
            Solution.prioritize(new String[]{"name|10|2"}));
        expectIllegalArgument("invalid request at index 0", () ->
            Solution.prioritize(new String[]{"name|-1|2"}));
        expectIllegalArgument("invalid request at index 0", () ->
            Solution.prioritize(new String[]{"name|1|-1"}));
        expectIllegalArgument("invalid request at index 0", () ->
            Solution.prioritize(new String[]{"name|1|9223372036854775808"}));
        expectIllegalArgument("invalid request at index 0", () ->
            Solution.prioritize(new String[]{"name|x|0"}));
        expectIllegalArgument("invalid request at index 0", () ->
            Solution.prioritize(new String[]{"name|1|1x"}));
    }

    private static void expectIllegalArgument(String message, Runnable action) {
        try {
            action.run();
            throw new AssertionError("expected IllegalArgumentException: " + message);
        } catch (IllegalArgumentException ex) {
            if (!message.equals(ex.getMessage())) {
                throw new AssertionError(
                    "expected message <" + message + "> but was <" + ex.getMessage() + ">"
                );
            }
        }
    }

    private static void assertListEquals(List<String> expected, List<String> actual) {
        if (!expected.equals(actual)) {
            throw new AssertionError("expected " + expected + " but was " + actual);
        }
    }
}

