import java.util.Arrays;
import java.util.List;

public class SolutionTest {
    public static void main(String[] args) {
        testRankingAndSelection();
        testScoreBoundaries();
        testEmptyZeroLimitAndNonMutation();
        testDuplicateEntries();
        testInvalidInputs();
    }

    private static void testRankingAndSelection() {
        String[] entries = {
            "zeta:8",
            "alpha:8",
            "winner:20",
            "negative:-3",
            "beta:8"
        };
        assertListEquals(
            Arrays.asList("winner", "alpha", "beta"),
            Solution.selectWinners(entries, 3)
        );
    }

    private static void testScoreBoundaries() {
        String[] entries = {
            "lowest:-1000",
            "zero:0",
            "highest:1000",
            "also-highest:1000"
        };
        assertListEquals(
            Arrays.asList("also-highest", "highest", "zero", "lowest"),
            Solution.selectWinners(entries, 4)
        );
    }

    private static void testEmptyZeroLimitAndNonMutation() {
        assertListEquals(
            Arrays.asList(),
            Solution.selectWinners(new String[0], 0)
        );

        String[] entries = {"b:1", "a:2"};
        String[] snapshot = entries.clone();
        assertListEquals(Arrays.asList(), Solution.selectWinners(entries, 0));
        if (!Arrays.equals(snapshot, entries)) {
            throw new AssertionError("input array was modified for zero limit");
        }

        Solution.selectWinners(entries, entries.length);
        if (!Arrays.equals(snapshot, entries)) {
            throw new AssertionError("input array was modified");
        }
    }

    private static void testDuplicateEntries() {
        String[] entries = {"same:5", "other:9", "same:5", "last:1"};
        assertListEquals(
            Arrays.asList("other", "same", "same", "last"),
            Solution.selectWinners(entries, 4)
        );
    }

    private static void testInvalidInputs() {
        expectIllegalArgument("entries must not be null", () ->
            Solution.selectWinners(null, 0));
        expectIllegalArgument("invalid limit", () ->
            Solution.selectWinners(new String[]{"ok:1"}, -1));
        expectIllegalArgument("invalid limit", () ->
            Solution.selectWinners(new String[]{"ok:1"}, 2));
        expectIllegalArgument("invalid entry at index 1", () ->
            Solution.selectWinners(new String[]{"ok:1", null}, 1));
        expectIllegalArgument("invalid entry at index 0", () ->
            Solution.selectWinners(new String[]{"missing"}, 1));
        expectIllegalArgument("invalid entry at index 0", () ->
            Solution.selectWinners(new String[]{"too:many:colons"}, 1));
        expectIllegalArgument("invalid entry at index 0", () ->
            Solution.selectWinners(new String[]{"Upper:1"}, 1));
        expectIllegalArgument("invalid entry at index 0", () ->
            Solution.selectWinners(new String[]{"bad_label:1"}, 1));
        expectIllegalArgument("invalid entry at index 0", () ->
            Solution.selectWinners(new String[]{"label:1001"}, 1));
        expectIllegalArgument("invalid entry at index 0", () ->
            Solution.selectWinners(new String[]{"label:-1001"}, 1));
        expectIllegalArgument("invalid entry at index 0", () ->
            Solution.selectWinners(new String[]{"label:not-a-number"}, 1));
        expectIllegalArgument("invalid entry at index 0", () ->
            Solution.selectWinners(new String[]{":1"}, 1));
        expectIllegalArgument("invalid entry at index 0", () ->
            Solution.selectWinners(new String[]{"label:"}, 1));
    }

    private static void expectIllegalArgument(String message, Runnable action) {
        try {
            action.run();
            throw new AssertionError("expected IllegalArgumentException: " + message);
        } catch (IllegalArgumentException ex) {
            if (!message.equals(ex.getMessage())) {
                throw new AssertionError(
                    "expected message <" + message + "> but was <" + ex.getMessage() + ">"
                );
            }
        }
    }

    private static void assertListEquals(List<String> expected, List<String> actual) {
        if (!expected.equals(actual)) {
            throw new AssertionError("expected " + expected + " but was " + actual);
        }
    }
}

