    private static void testStableTies() {
        assertArrayEquals(
            new int[]{0, 2, 4, 1, 3},
            Solution.stableRank(new int[]{5, 1, 5, 1, 5})
        );
        assertArrayEquals(
            new int[]{0, 1, 2, 3},
            Solution.stableRank(new int[]{8, 8, 8, 8})
        );
    }

    private static void testExtremePriorities() {
        assertArrayEquals(
            new int[]{1, 3, 2, 0},
            Solution.stableRank(new int[]{Integer.MIN_VALUE, Integer.MAX_VALUE, 0, Integer.MAX_VALUE})
        );
    }

    private static void testEmptyAndSingleton() {
        assertArrayEquals(new int[0], Solution.stableRank(new int[0]));
        assertArrayEquals(new int[]{0}, Solution.stableRank(new int[]{42}));
    }

    private static void testInputNotModified() {
        int[] priorities = {4, -2, 4, 10, 0};
        int[] snapshot = priorities.clone();
        Solution.stableRank(priorities);
        assertArrayEquals(snapshot, priorities);
    }

    private static void assertArrayEquals(int[] expected, int[] actual) {
