import java.util.Arrays;

public class SolutionTest {
    public static void main(String[] args) {
        testSortingAndCanonicalEncoding();
        testReplacement();
        testStateIsolation();
        testEmptyInputsAndValues();
        testPrintableAsciiBoundaries();
        testInputNotModified();
    }

    private static void testSortingAndCanonicalEncoding() {
        String[] records = {
            "z=last;a=hello%20world;m=A_z-9.%7e",
            "b=%3d%3B%25;a=plain"
        };
        assertArrayEquals(
            new String[]{
                "a=hello%20world;m=A_z-9.%7E;z=last",
                "a=plain;b=%3D%3B%25"
            },
            Solution.normalizeRecords(records)
        );
    }

    private static void testReplacement() {
        assertArrayEquals(
            new String[]{"a=third%20value;b=keep"},
            Solution.normalizeRecords(new String[]{"a=first;b=keep;a=second;a=third%20value"})
        );
    }

    private static void testStateIsolation() {
        assertArrayEquals(
            new String[]{"a=one;b=two", "", "c=three", "a=four"},
            Solution.normalizeRecords(new String[]{"b=two;a=one", "", "c=three", "a=four"})
        );
    }

    private static void testEmptyInputsAndValues() {
        assertArrayEquals(new String[0], Solution.normalizeRecords(new String[0]));
        assertArrayEquals(
            new String[]{"", "a=", "a=;b="},
            Solution.normalizeRecords(new String[]{"", "a=", "b=;a="})
        );
    }

    private static void testPrintableAsciiBoundaries() {
        assertArrayEquals(
            new String[]{"value=%20%21%7E"},
            Solution.normalizeRecords(new String[]{"value=%20%21%7e"})
        );
        assertArrayEquals(
            new String[]{"value=AZaz09._-"},
            Solution.normalizeRecords(new String[]{"value=%41%5A%61%7A%30%39%2E%5F%2D"})
        );
    }

    private static void testInputNotModified() {
        String[] records = {"b=two;a=one", "x=%25", ""};
        String[] snapshot = records.clone();
        Solution.normalizeRecords(records);
        assertArrayEquals(snapshot, records);
    }

    private static void assertArrayEquals(String[] expected, String[] actual) {
        if (!Arrays.equals(expected, actual)) {
            throw new AssertionError(
                "expected " + Arrays.toString(expected) + " but was " + Arrays.toString(actual)
            );
        }
    }
}

