import java.util.Arrays;

public class SolutionTest {
    public static void main(String[] args) {
        assertArrayEquals(new int[] {4, 5, 1, 2, 3},
                Solution.rotateRight(new int[] {1, 2, 3, 4, 5}, 2), "normal rotation");
        assertArrayEquals(new int[] {3, 4, 1, 2},
                Solution.rotateRight(new int[] {1, 2, 3, 4}, 6), "distance wraps modulo length");
        assertArrayEquals(new int[] {2, 3, 1},
                Solution.rotateRight(new int[] {1, 2, 3}, Integer.MAX_VALUE), "maximum distance");
        assertArrayEquals(new int[] {-1, 0, Integer.MIN_VALUE, Integer.MAX_VALUE},
                Solution.rotateRight(new int[] {Integer.MIN_VALUE, Integer.MAX_VALUE, -1, 0}, 2),
                "integer values are preserved");

        int[] zeroInput = {7, 8, 9};
        int[] zeroOutput = Solution.rotateRight(zeroInput, 0);
        assertArrayEquals(new int[] {7, 8, 9}, zeroOutput, "zero distance contents");
        assertNotSame(zeroInput, zeroOutput, "zero distance must allocate a new array");

        int[] fullInput = {10, 20, 30};
        int[] fullOutput = Solution.rotateRight(fullInput, 3);
        assertArrayEquals(new int[] {10, 20, 30}, fullOutput, "full-length distance contents");
        assertNotSame(fullInput, fullOutput, "full-length distance must allocate a new array");

        int[] singletonInput = {42};
        int[] singletonOutput = Solution.rotateRight(singletonInput, Integer.MAX_VALUE);
        assertArrayEquals(new int[] {42}, singletonOutput, "singleton boundary");
        assertNotSame(singletonInput, singletonOutput, "singleton result must be newly allocated");

        int[] input = {1, 2, 3, 4};
        int[] inputSnapshot = input.clone();
        int[] output = Solution.rotateRight(input, 1);
        assertArrayEquals(inputSnapshot, input, "call must not modify input");
        output[0] = 99;
        assertArrayEquals(inputSnapshot, input, "mutating output must not affect input");
        input[0] = 77;
        assertArrayEquals(new int[] {99, 1, 2, 3}, output, "mutating input must not affect output");
    }

    private static void assertArrayEquals(int[] expected, int[] actual, String message) {
        if (!Arrays.equals(expected, actual)) {
            throw new AssertionError(message + ": expected " + Arrays.toString(expected)
                    + " but was " + Arrays.toString(actual));
        }
    }

    private static void assertNotSame(Object first, Object second, String message) {
        if (first == second) {
            throw new AssertionError(message);
        }
    }
}

