public final class Solution {
    private Solution() {
    }

    public static int[][] shiftRows(int[][] rows) {
        int[][] shifted = new int[rows.length][];
        for (int r = 0; r < rows.length; r++) {
            int length = rows[r].length;
            int distance = r % length;
            shifted[r] = new int[length];
            for (int i = 0; i < length; i++) {
                shifted[r][i] = rows[r][(i + distance) % length];
            }
        }
        return shifted;
    }
