import java.util.Arrays;

public class SolutionTest {
    public static void main(String[] args) {
        assertStrings(new String[0], Solution.finalStates(new String[0][]), "empty outer array");

        String[][] workflows = {
            {},
            {"START"},
            {"START", "FINISH"},
            {"START", "PAUSE"},
            {"START", "PAUSE", "RESUME", "FINISH"},
            {"FINISH", "PAUSE", "RESUME"},
            {"START", "START", "PAUSE", "PAUSE", "FINISH", "RESUME", "FINISH"},
            {"START", "FINISH", "PAUSE", "RESUME", "START"}
        };
        String[][] snapshot = clone2d(workflows);
        assertStrings(new String[] {
                "NEW", "RUNNING", "DONE", "PAUSED", "DONE", "NEW", "DONE", "DONE"
            },
            Solution.finalStates(workflows),
            "independent workflows and invalid transitions");
        assertDeepEquals(snapshot, workflows, "workflows were modified");

        assertStrings(new String[] {"DONE", "NEW", "RUNNING"},
                Solution.finalStates(new String[][] {
                    {"START", "FINISH"},
                    {},
                    {"START", "PAUSE", "RESUME"}
                }),
                "state resets for every workflow");

        String[][] many = new String[100][];
        String[] expectedMany = new String[100];
        for (int i = 0; i < many.length; i++) {
            if (i % 4 == 0) {
                many[i] = new String[0];
                expectedMany[i] = "NEW";
            } else if (i % 4 == 1) {
                many[i] = new String[] {"START"};
                expectedMany[i] = "RUNNING";
            } else if (i % 4 == 2) {
                many[i] = new String[] {"START", "PAUSE"};
                expectedMany[i] = "PAUSED";
            } else {
                many[i] = new String[] {"START", "FINISH"};
                expectedMany[i] = "DONE";
            }
        }
        assertStrings(expectedMany, Solution.finalStates(many), "many independent workflows");
    }

    private static String[][] clone2d(String[][] input) {
        String[][] copy = input.clone();
        for (int i = 0; i < copy.length; i++) {
            copy[i] = input[i].clone();
        }
        return copy;
    }

    private static void assertDeepEquals(String[][] expected, String[][] actual, String label) {
        if (!Arrays.deepEquals(expected, actual)) {
            throw new AssertionError(label);
        }
    }

    private static void assertStrings(String[] expected, String[] actual, String label) {
        if (!Arrays.equals(expected, actual)) {
            throw new AssertionError(label + ": expected " + Arrays.toString(expected)
                    + " but was " + Arrays.toString(actual));
        }
    }
}

