import java.text.Normalizer;
import java.util.ArrayList;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Locale;
import java.util.Set;

public final class Solution {
    public static List<String> uniqueSlices(String text, int sliceLength) {
        if (sliceLength <= 0) {
            throw new IllegalArgumentException("sliceLength must be positive");
        }

        String normalized = Normalizer.normalize(text, Normalizer.Form.NFC);
        StringBuilder compact = new StringBuilder();
        normalized.codePoints().forEach(cp -> {
            if (!Character.isWhitespace(cp) && !Character.isSpaceChar(cp)) {
                compact.appendCodePoint(cp);
            }
        });
        String canonical = Normalizer.normalize(
                compact.toString().toLowerCase(Locale.ROOT), Normalizer.Form.NFC);
        int count = canonical.codePointCount(0, canonical.length());
        Set<String> slices = new LinkedHashSet<String>();

        for (int start = 0; start + sliceLength <= count; start++) {
            int from = canonical.offsetByCodePoints(0, start);
            int to = canonical.offsetByCodePoints(from, sliceLength);
            slices.add(canonical.substring(from, to));
        }
        return new ArrayList<String>(slices);
    }
}

