import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;

public class SolutionTest {
    public static void main(String[] args) {
        String grin = "\uD83D\uDE00";
        String music = "\uD834\uDD1E";
        List<String> input = new ArrayList<String>(Arrays.asList(
                "abc",
                "A" + grin + "B",
                grin + music,
                "e\u0301",
                "",
                "x"));
        List<String> snapshot = new ArrayList<String>(input);

        List<String> result = Solution.reverseText(input);
        assertListEquals(Arrays.asList(
                "cba",
                "B" + grin + "A",
                music + grin,
                "\u0301e",
                "",
                "x"), result);
        assertListEquals(snapshot, input);
        if (result == input) {
            throw new AssertionError("Returned list aliases input list");
        }

        result.set(0, "changed-result");
        assertEquals("abc", input.get(0));

        input.set(1, "changed-input");
        assertEquals("B" + grin + "A", result.get(1));

        List<String> emptyInput = new ArrayList<String>();
        List<String> emptyResult = Solution.reverseText(emptyInput);
        assertListEquals(Collections.<String>emptyList(), emptyResult);
        if (emptyInput == emptyResult) {
            throw new AssertionError("Empty returned list aliases input list");
        }
    }

    private static void assertEquals(String expected, String actual) {
        if (!expected.equals(actual)) {
            throw new AssertionError("Expected " + expected + " but got " + actual);
        }
    }

    private static void assertListEquals(List<String> expected, List<String> actual) {
        if (!expected.equals(actual)) {
            throw new AssertionError("Expected " + expected + " but got " + actual);
        }
    }
}

