function encodePacket(packet) {
  const output = new Uint8Array(packet.payload.length + 3);

  output[0] =
    (packet.channel & 0x1f) |
    (packet.acknowledged ? 0x20 : 0) |
    (packet.encrypted ? 0x40 : 0);
  output[1] = packet.payload.length;

  for (let index = 0; index < packet.payload.length; index += 1) {
    const value = packet.payload[index];
    output[index + 2] = ((value << 1) | (value >>> 7)) & 0xff;
  }

  let checksum = 0;
  for (let index = 0; index < output.length - 1; index += 1) {
    checksum ^= output[index];
  }
  output[output.length - 1] = checksum;

  return output;
}

module.exports = { encodePacket };

