function runPipeline(steps, initialValue, done) {
  let index = 0;
  let finished = false;

  function finish(error, value) {
    if (finished) {
      return;
    }
    finished = true;
    done(error, value);
  }

  function advance(value) {
    if (finished) {
      return;
    }
    if (index === steps.length) {
      finish(null, value);
      return;
    }

    const step = steps[index++];
    let continued = false;

    function next(error, nextValue) {
      if (continued || finished) {
        return;
      }
      continued = true;
      if (error != null) {
        finish(error);
      } else {
        advance(nextValue);
      }
    }

    try {
      step(value, next);
    } catch (error) {
      if (!continued) {
        continued = true;
        finish(error);
      }
    }
  }

  advance(initialValue);
}

module.exports = { runPipeline };

