      }
      if (current.length === 0) {
        topics.delete(topic);
      }
    };
  }

  function emit(topic, payload, done) {
    const queue = (topics.get(topic) || []).slice();
    let index = 0;
    let finished = false;

    function finish(error) {
      if (finished) {
        return;
      }
      finished = true;
      done(error);
    }

    function advance() {
      if (finished) {
        return;
      }
      if (index === queue.length) {
