    bus.on('x', () => { reached = true; });
    bus.emit('x', null, (error) => {
      doneCalls += 1;
      assert.strictEqual(error, failure);
    });
    assert.strictEqual(reached, false);
    assert.strictEqual(doneCalls, 1);
