function resolveDependencyOrder(graph, roots) {
  const resolved = new Set();
  const order = [];

  function visit(node) {
    if (resolved.has(node)) {
      return;
    }

    resolved.add(node);
    const dependencies = graph[node] || [];

    for (const dependency of dependencies) {
      visit(dependency);
    }

    order.push(node);
  }

  for (const root of roots) {
    visit(root);
  }

  return order;
}

module.exports = resolveDependencyOrder;

