function compareText(a, b) {
  if (a < b) return -1;
  if (a > b) return 1;
  return 0;
}

function rankChoices(ballots) {
  const selectedByVoter = new Map();

  for (let index = 0; index < ballots.length; index += 1) {
    const ballot = ballots[index];
    const current = selectedByVoter.get(ballot.voter);

    if (current === undefined || ballot.sequence > current.ballot.sequence) {
      selectedByVoter.set(ballot.voter, { ballot, index });
    }
  }

  const counts = new Map();
  for (const { ballot } of selectedByVoter.values()) {
    counts.set(ballot.choice, (counts.get(ballot.choice) || 0) + 1);
  }

  return Array.from(counts, ([choice, count]) => ({ choice, count }))
    .sort((a, b) => {
      if (a.count !== b.count) return b.count - a.count;
      return compareText(a.choice, b.choice);
    });
}

module.exports = { rankChoices };

