  if (a < b) return -1;
  if (a > b) return 1;
  return 0;
}

function rankChoices(ballots) {
  const selectedByVoter = new Map();

  for (let index = 0; index < ballots.length; index += 1) {
    const ballot = ballots[index];
    const current = selectedByVoter.get(ballot.voter);

    if (current === undefined || ballot.sequence > current.ballot.sequence) {
