function createSeatHoldManager(capacity) {
  let available = capacity;
  const holds = new Map();
  const commandResults = new Map();

  function dispatch(command) {
    if (commandResults.has(command.commandId)) {
      return commandResults.get(command.commandId);
    }

    let result;

    if (command.type === 'hold') {
      if (holds.has(command.holdId)) {
        throw new Error('Hold already exists');
      }
      if (command.seats > available) {
        throw new Error('Insufficient seats');
      }

      holds.set(command.holdId, {
        seats: command.seats,
        status: 'ACTIVE'
      });
      available -= command.seats;
      result = 'ACTIVE';
    } else if (command.type === 'commit' || command.type === 'cancel') {
      const hold = holds.get(command.holdId);
      if (!hold) {
        throw new Error('Unknown hold');
      }
      if (hold.status !== 'ACTIVE') {
        throw new Error('Hold is not active');
      }

      if (command.type === 'commit') {
        hold.status = 'COMMITTED';
        result = 'COMMITTED';
      } else {
        hold.status = 'CANCELLED';
        available += hold.seats;
        result = 'CANCELLED';
      }
    } else {
      throw new Error('Unsupported command');
    }

    commandResults.set(command.commandId, result);
    return result;
  }

  function getAvailable() {
    return available;
  }

  function getHoldStatus(holdId) {
    const hold = holds.get(holdId);
    return hold ? hold.status : undefined;
  }

  return { dispatch, getAvailable, getHoldStatus };
}

module.exports = { createSeatHoldManager };

