function decodeCodePointEscapes(source) {
  if (typeof source !== 'string') {
    throw new TypeError('Source must be a string');
  }

  let output = '';
  let index = 0;

  while (index < source.length) {
    if (source.startsWith('\\u{', index)) {
      const close = source.indexOf('}', index + 3);
      if (close === -1) {
        throw new SyntaxError('Unclosed Unicode escape');
      }

      const digits = source.slice(index + 3, close);
      if (!/^[0-9A-Fa-f]{1,6}$/.test(digits)) {
        throw new SyntaxError('Invalid Unicode escape');
      }

      const codePoint = Number.parseInt(digits, 16);
      if (
        codePoint > 0x10ffff ||
        (codePoint >= 0xd800 && codePoint <= 0xdfff)
      ) {
        throw new RangeError('Invalid Unicode code point');
      }

      output += String.fromCodePoint(codePoint);
      index = close + 1;
    } else {
      output += source[index];
      index += 1;
    }
  }

  return output;
}

module.exports = decodeCodePointEscapes;

