```

Build an index from each SKU to all matching items. Map keys must follow first-occurrence order, and items within each bucket must retain their input order.

The result must be an immutable snapshot with respect to aliasing: do not mutate the input array or its objects, allocate a new bucket for every SKU, and place a newly allocated copy of every item in its bucket. Consequently, changing an original item after the call must not alter the indexed copy, and no returned item may be identical to an input object.

Use only the JavaScript/TypeScript standard library. Perform no filesystem, network, clock, or random operations. Return one complete source file with the requested exports.

Return only the complete source file; do not include Markdown fences or prose.

export interface CatalogItem {
  sku: string;
  warehouse: string;
  quantity: number;
}

export function indexCatalog(
  items: readonly CatalogItem[],
): ReadonlyMap<string, readonly CatalogItem[]> {
  const index = new Map<string, CatalogItem[]>();

  for (const item of items) {
    let bucket = index.get(item.sku);
    if (bucket === undefined) {
      bucket = [];
      index.set(item.sku, bucket);
    }
    bucket.push({
      sku: item.sku,
      warehouse: item.warehouse,
      quantity: item.quantity,
    });
  }

  return index;
}

