const second: CatalogItem = { sku: "SKU-1", warehouse: "north", quantity: 7 };
const third: CatalogItem = { sku: "SKU-2", warehouse: "east", quantity: 0 };
const repeated: CatalogItem = { sku: "SKU-3", warehouse: "central", quantity: 9 };
