```ts
export interface BinaryChunk {
  readonly tag: number;
  readonly bytes: Uint8Array;
}

export function encodeChunks(chunks: readonly BinaryChunk[]): Uint8Array;
```

Inputs satisfy these preconditions: every `tag` is an integer from 0 through 255, and every `bytes` array has at most 65,535 elements.

Encode chunks in ascending `tag` order. Ordering must be stable: chunks with equal tags retain their original relative order. Do not reorder the supplied array itself.

Encode each sorted chunk as one tag byte, a two-byte unsigned big-endian payload length, and the payload bytes. Append one final checksum byte equal to the bitwise XOR of every preceding output byte. Thus, an empty input produces a one-byte array containing zero.

Use only the JavaScript/TypeScript standard library. Perform no filesystem, network, clock, or random operations. Return one complete source file with the requested exports.

Return only the complete source file; do not include Markdown fences or prose.

export interface BinaryChunk {
  readonly tag: number;
  readonly bytes: Uint8Array;
}

export function encodeChunks(chunks: readonly BinaryChunk[]): Uint8Array {
  const ordered = chunks
    .map((chunk, position) => ({ chunk, position }))
    .sort((left, right) =>
      left.chunk.tag - right.chunk.tag || left.position - right.position,
    );

  const encoded: number[] = [];
  let checksum = 0;

  const append = (byte: number): void => {
    encoded.push(byte);
    checksum ^= byte;
  };

  for (const { chunk } of ordered) {
    append(chunk.tag);
    append((chunk.bytes.length >>> 8) & 0xff);
    append(chunk.bytes.length & 0xff);
    for (const byte of chunk.bytes) {
      append(byte);
    }
  }

  encoded.push(checksum & 0xff);
  return Uint8Array.from(encoded);
}

