import { encodeChunks, type BinaryChunk } from "./solution";

function assert(condition: boolean, message: string): void {
  if (!condition) throw new Error(message);
}

function assertBytes(actual: Uint8Array, expected: readonly number[], message: string): void {
  assert(actual.length === expected.length, `${message}: length`);
  for (let i = 0; i < expected.length; i += 1) {
    assert(actual[i] === expected[i], `${message}: byte ${i}`);
  }
}

assertBytes(encodeChunks([]), [0], "empty encoding");

const firstPayload = new Uint8Array([0x10]);
const secondPayload = new Uint8Array([0xaa, 0xbb]);
const thirdPayload = new Uint8Array([0x20, 0x21]);
const chunks: BinaryChunk[] = [
  { tag: 2, bytes: firstPayload },
  { tag: 1, bytes: secondPayload },
  { tag: 2, bytes: thirdPayload },
];
const originalChunkOrder = chunks.slice();
const payloadSnapshots = chunks.map((chunk) => Array.from(chunk.bytes));

const encoded = encodeChunks(chunks);
assertBytes(
  encoded,
  [1, 0, 2, 0xaa, 0xbb, 2, 0, 1, 0x10, 2, 0, 2, 0x20, 0x21, 0],
  "sorted stable encoding with checksum",
);
for (let i = 0; i < chunks.length; i += 1) {
  assert(chunks[i] === originalChunkOrder[i], `input chunk order changed at ${i}`);
  assertBytes(chunks[i].bytes, payloadSnapshots[i], `payload mutated at ${i}`);
}
firstPayload[0] = 0xff;
assert(encoded[8] === 0x10, "encoded output must contain copied payload bytes");

const largestPayload = new Uint8Array(65535);
largestPayload[0] = 1;
largestPayload[65534] = 2;
const boundaryChunks: BinaryChunk[] = [
  { tag: 255, bytes: largestPayload },
  { tag: 0, bytes: new Uint8Array(0) },
];
const boundary = encodeChunks(boundaryChunks);
assert(boundary.length === 65542, "boundary encoding length");
assertBytes(boundary.slice(0, 6), [0, 0, 0, 255, 255, 255], "zero and maximum tag/length headers");
assert(boundary[6] === 1, "first maximum-length payload byte");
assert(boundary[65540] === 2, "last maximum-length payload byte");
assert(boundary[65541] === 252, "boundary checksum");
largestPayload[0] = 9;
assert(boundary[6] === 1, "boundary output must not alias its payload");

