import { inspectParentTree } from "./solution";
import type { ParentLink } from "./solution";

function assert(condition: unknown, message: string): asserts condition {
  if (!condition) throw new Error(message);
}

function equalStrings(actual: readonly string[], expected: readonly string[], message: string): void {
  assert(actual.length === expected.length, message + " (length)");
  for (let i = 0; i < expected.length; i++) {
    assert(actual[i] === expected[i], message + " (index " + i + ")");
  }
}

function expectRangeError(action: () => void, message: string): void {
  let caught: unknown;
  try {
    action();
  } catch (error: unknown) {
    caught = error;
  }
  assert(caught instanceof RangeError, "expected RangeError: " + message);
  assert(caught.message === message, "unexpected error message for " + message);
}

{
  const links: ParentLink[] = [
    { id: "early-child", parentId: "branch-a" },
    { id: "root", parentId: null },
    { id: "branch-a", parentId: "root" },
    { id: "branch-b", parentId: "root" },
    { id: "late-child", parentId: "branch-a" },
    { id: "leaf-b", parentId: "branch-b" },
  ];
  const before = JSON.stringify(links);
  const report = inspectParentTree(links);

  assert(report.rootId === "root", "root ID");
  equalStrings(
    report.preorder,
    ["root", "branch-a", "early-child", "late-child", "branch-b", "leaf-b"],
    "preorder must preserve child input order",
  );
  assert(report.depthById["root"] === 0, "root depth");
  assert(report.depthById["branch-a"] === 1, "branch depth");
  assert(report.depthById["early-child"] === 2, "early child depth");
  assert(report.depthById["late-child"] === 2, "late child depth");
