import { buildRunQueue } from './solution';

function assert(condition: boolean, message: string): void {
  if (!condition) throw new Error(message);
}

function assertEqual<T>(actual: T, expected: T, message: string): void {
  if (actual !== expected) {
    throw new Error(`${message}: expected ${String(expected)}, got ${String(actual)}`);
  }
}

function assertJsonEqual(actual: unknown, expected: unknown, message: string): void {
  const actualJson = JSON.stringify(actual);
  const expectedJson = JSON.stringify(expected);
  if (actualJson !== expectedJson) {
    throw new Error(`${message}: expected ${expectedJson}, got ${actualJson}`);
  }
}

assertJsonEqual(buildRunQueue([], 10), [], 'empty input must produce an empty queue');

const malformed: readonly unknown[] = [
  null,
  [],
  'job',
  {},
  { jobId: '', revision: 0, urgency: 0, duration: 1 },
  { jobId: ' \t\n ', revision: 0, urgency: 0, duration: 1 },
  { jobId: 1, revision: 0, urgency: 0, duration: 1 },
  { jobId: 'a', revision: -1, urgency: 0, duration: 1 },
  { jobId: 'a', revision: 1.5, urgency: 0, duration: 1 },
  { jobId: 'a', revision: 0, urgency: -1, duration: 1 },
  { jobId: 'a', revision: 0, urgency: 6, duration: 1 },
  { jobId: 'a', revision: 0, urgency: 1.5, duration: 1 },
  { jobId: 'a', revision: 0, urgency: 0, duration: 0 },
  { jobId: 'a', revision: 0, urgency: 0, duration: -1 },
  { jobId: 'a', revision: 0, urgency: 0, duration: 1.5 },
  { jobId: 'a', revision: Infinity, urgency: 0, duration: 1 },
];
assertJsonEqual(buildRunQueue(malformed, 20), [], 'all malformed entries must be ignored');

const entries = [
  { jobId: 'revision', revision: 1, urgency: 5, duration: 1 },
  { jobId: 'revision', revision: 2, urgency: 0, duration: 99 },
  { jobId: 'urgency-version', revision: 3, urgency: 2, duration: 1 },
  { jobId: 'urgency-version', revision: 3, urgency: 4, duration: 20 },
  { jobId: 'duration-version', revision: 2, urgency: 3, duration: 8 },
  { jobId: 'duration-version', revision: 2, urgency: 3, duration: 4 },
  { jobId: 'a', revision: 0, urgency: 4, duration: 5, extra: 'ignored' },
  { jobId: 'A', revision: 0, urgency: 4, duration: 5 },
  { jobId: 'low', revision: 100, urgency: 1, duration: 1 },
  { jobId: '   ', revision: 999, urgency: 5, duration: 1 },
];
const before = JSON.stringify(entries);
const queue = buildRunQueue(entries, 20);
assertJsonEqual(
  queue,
  [
    { jobId: 'urgency-version', revision: 3, urgency: 4, duration: 20 },
    { jobId: 'duration-version', revision: 2, urgency: 3, duration: 4 },
    { jobId: 'A', revision: 0, urgency: 4, duration: 5 },
    { jobId: 'a', revision: 0, urgency: 4, duration: 5 },
    { jobId: 'low', revision: 100, urgency: 1, duration: 1 },
    { jobId: 'revision', revision: 2, urgency: 0, duration: 99 },
  ].sort((left, right) => {
    if (left.urgency !== right.urgency) return right.urgency - left.urgency;
    if (left.duration !== right.duration) return left.duration - right.duration;
    return left.jobId < right.jobId ? -1 : left.jobId > right.jobId ? 1 : 0;
  }),
  'version selection and final queue ordering must use their distinct specified rules',
);
assertEqual(JSON.stringify(entries), before, 'entries must not be mutated');
for (const result of queue) {
  assert(!entries.some((entry) => entry === result), `returned job ${result.jobId} must be newly allocated`);
  assertJsonEqual(Object.keys(result).sort(), ['duration', 'jobId', 'revision', 'urgency'], 'returned jobs must contain only queue fields');
}

const limited = buildRunQueue(entries, 3);
assertJsonEqual(limited, queue.slice(0, 3), 'capacity must truncate the ordered winners');
assertJsonEqual(buildRunQueue(entries, 0), [], 'zero capacity must return an empty queue');

limited[0].duration = 999;
assertEqual(entries[3].duration, 20, 'mutating a returned job must not affect input');

const earlierTie = buildRunQueue([
  { jobId: 'same', revision: 1, urgency: 2, duration: 3 },
  { jobId: 'same', revision: 1, urgency: 2, duration: 3 },
], 1);
assertJsonEqual(earlierTie, [{ jobId: 'same', revision: 1, urgency: 2, duration: 3 }], 'equal versions must still yield exactly one job');

