interface ParsedPair {
  key: string;
  value: string;
  index: number;
}

const COMPONENT_PATTERN = /^(?:[A-Za-z0-9_.!~*'()-]|%[0-9A-Fa-f]{2})*$/;

function compareText(left: string, right: string): number {
  return left < right ? -1 : left > right ? 1 : 0;
}

function decodeComponent(component: string): string {
  if (!COMPONENT_PATTERN.test(component)) {
    throw new Error("Invalid encoded pairs");
  }
  try {
    return decodeURIComponent(component);
  } catch {
    throw new Error("Invalid encoded pairs");
  }
}

export function canonicalizeEncodedPairs(text: string): string {
  if (text === "") {
    return "";
  }

  const pairs: ParsedPair[] = text.split("&").map((segment, index) => {
    const separator = segment.indexOf("=");
    if (separator < 0 || separator !== segment.lastIndexOf("=")) {
      throw new Error("Invalid encoded pairs");
    }

    const key = decodeComponent(segment.slice(0, separator));
    const value = decodeComponent(segment.slice(separator + 1));
    if (key.length === 0) {
      throw new Error("Invalid encoded pairs");
    }
    return { key, value, index };
  });

  pairs.sort((left, right) => {
    const byKey = compareText(left.key, right.key);
    if (byKey !== 0) {
      return byKey;
    }
    const byValue = compareText(left.value, right.value);
    return byValue !== 0 ? byValue : left.index - right.index;
  });

  return pairs
    .map(({ key, value }) => `${encodeURIComponent(key)}=${encodeURIComponent(value)}`)
    .join("&");
}

