Implement consecutive-run compression for an ordered sequence.

Export exactly this API:

```typescript
export interface Run<T> {
    value: T;
    count: number;
}

export function compressRuns<T>(
    items: readonly T[],
    same: (left: T, right: T) => boolean,
): Run<T>[];
```

Scan `items` from left to right and replace each maximal consecutive run of equivalent items with one `Run`. Use `same` to compare an item only with the representative value of the current run. Store the first item of a run as its `value` and the run length as `count`.

Equivalent values separated by a non-equivalent item belong to different runs. For example, an `A, B, A` sequence produces three runs even when the two `A` values are equivalent. An empty input produces an empty array.

The implementation must be deterministic and use no filesystem, network, clock, randomness, external package, or framework.

Return only the complete source file; do not include Markdown fences or prose.

export interface Run<T> {
    value: T;
    count: number;
}

export function compressRuns<T>(
    items: readonly T[],
    same: (left: T, right: T) => boolean,
): Run<T>[] {
    const runs: Run<T>[] = [];

    for (const item of items) {
        const current = runs[runs.length - 1];
        if (current !== undefined && same(current.value, item)) {
            current.count += 1;
        } else {
            runs.push({ value: item, count: 1 });
        }
    }

    return runs;
}

