import { compressRuns, Run } from './solution';

function assert(condition: boolean, message: string): void {
    if (!condition) {
        throw new Error(message);
    }
}

function assertRuns<T>(actual: readonly Run<T>[], expected: readonly Run<T>[], message: string): void {
    assert(actual.length === expected.length, `${message}: unexpected run count`);
    for (let index = 0; index < expected.length; index += 1) {
        assert(actual[index].value === expected[index].value, `${message}: wrong value at run ${index}`);
        assert(actual[index].count === expected[index].count, `${message}: wrong count at run ${index}`);
    }
}

let emptyComparisons = 0;
assertRuns(
    compressRuns<number>([], () => {
        emptyComparisons += 1;
        return true;
    }),
    [],
    'empty input',
);
assert(emptyComparisons === 0, 'empty input must not invoke the comparator');

assertRuns(compressRuns([7], (left, right) => left === right), [{ value: 7, count: 1 }], 'singleton');
assertRuns(
    compressRuns(['A', 'A', 'B', 'A', 'A'], (left, right) => left === right),
    [
        { value: 'A', count: 2 },
        { value: 'B', count: 1 },
        { value: 'A', count: 2 },
    ],
    'only consecutive equivalent values are combined',
