function assert(condition: boolean, message: string): void {
  if (!condition) throw new Error(message);
}

function assertDeepEqual(actual: unknown, expected: unknown, message: string): void {
  assert(JSON.stringify(actual) === JSON.stringify(expected), message);
}

const entries: LogEntry[] = [
  { key: "middle", score: 4, payload: "M" },
  { key: "highest", score: 9, payload: "H" },
  { key: "lowest", score: -2, payload: "L" },
  { key: "upper", score: 7, payload: "U" },
];
const original = entries.map((entry) => ({ ...entry }));

assertDeepEqual(
  rankWindow(entries, { offset: 1, limit: 2, direction: "asc" }),
  [
    { key: "middle", score: 4, payload: "M" },
    { key: "upper", score: 7, payload: "U" },
  ],
  "ascending window must be selected after sorting all entries",
);
assertDeepEqual(entries, original, "ascending ranking must not mutate the input");

assertDeepEqual(
  rankWindow(entries, { offset: 0, limit: 3, direction: "desc" }),
  [
    { key: "highest", score: 9, payload: "H" },
    { key: "upper", score: 7, payload: "U" },
    { key: "middle", score: 4, payload: "M" },
