  "a window may contain fewer entries than its limit",
);
assertDeepEqual(
  rankWindow(entries, { offset: entries.length, limit: 1, direction: "asc" }),
  [],
  "an offset at the sequence length must return an empty window",
);
assertDeepEqual(
  rankWindow(entries, { offset: 0, limit: 0, direction: "desc" }),
  [],
  "a zero limit must return an empty window",
);
assertDeepEqual(
  rankWindow([], { offset: 0, limit: 5, direction: "asc" }),
  [],
  "an empty input must return an empty window",
);

const returned = rankWindow(entries, { offset: 0, limit: entries.length, direction: "asc" });
assert(returned[0] !== entries[2], "each returned entry must be a new object");
assert(returned[1] !== entries[0], "all returned entries must be cloned");
returned[0].key = "changed";
returned[0].payload = "changed";
returned[0].score = 100;
assertDeepEqual(entries, original, "mutating a returned entry must not affect the input");

