export function splitOnSeparators(
  values: readonly number[],
  separator: number,
): number[][] {
  const segments: number[][] = [];
  const current: number[] = [];

  for (const value of values) {
    if (value === separator) {
      segments.push(current);
      current.length = 0;
    } else {
      current.push(value);
    }
  }

  segments.push(current);
  return segments;
}
