expectError("PACK.weightGrams must be a positive integer", () => workflow.apply({ type: "PACK", parcelCode: "P", weightGrams: -1 }));
expectError("PACK.weightGrams must be a positive integer", () => workflow.apply({ type: "PACK", parcelCode: "P", weightGrams: 1.5 }));
expectError("PACK.weightGrams must be a positive integer", () => workflow.apply({ type: "PACK", parcelCode: "P", weightGrams: Number.POSITIVE_INFINITY }));
