assertView(workflow.view(), { state: "PACKED", parcelCode: " P-1 ", weightGrams: 1 }, "invalid transitions must preserve parcel data");

assertView(workflow.apply({ type: "DISPATCH", extra: "ignored" }), { state: "DISPATCHED", parcelCode: " P-1 ", weightGrams: 1 }, "DISPATCH must retain parcel data");
expectError("invalid transition: DISPATCHED -> RESET", () => workflow.apply({ type: "RESET" }));
