export type ReviewState = "IDLE" | "REVIEWING" | "ACCEPTED" | "REJECTED";

export interface ReviewView {
  state: ReviewState;
  documentId: string | null;
  decisionNote: string | null;
}

type InputRecord = Record<string, unknown>;

function requireRecord(command: unknown): InputRecord {
  if (typeof command !== "object" || command === null || Array.isArray(command)) {
    throw new Error("command must be an object");
  }
  return command as InputRecord;
}

export class ReviewCycle {
  private state: ReviewState = "IDLE";
  private documentId: string | null = null;
  private decisionNote: string | null = null;

  apply(command: unknown): ReviewView {
    const record = requireRecord(command);
    const type = record.type;
    if (type !== "START" && type !== "DECIDE" && type !== "CLEAR") {
      throw new Error("type must be START, DECIDE, or CLEAR");
    }

    let nextDocumentId: string | null = null;
    let approved: boolean | null = null;
    let note: string | null = null;

    if (type === "START") {
      if (
        typeof record.documentId !== "string" ||
        record.documentId.trim().length === 0
      ) {
        throw new Error("START.documentId must be a non-empty string");
      }
      nextDocumentId = record.documentId;
    } else if (type === "DECIDE") {
      if (typeof record.approved !== "boolean") {
        throw new Error("DECIDE.approved must be a boolean");
      }
      if (typeof record.note !== "string" || record.note.trim().length === 0) {
        throw new Error("DECIDE.note must be a non-empty string");
      }
      approved = record.approved;
      note = record.note;
    }

    const allowed =
      (this.state === "IDLE" && type === "START") ||
      (this.state === "REVIEWING" && type === "DECIDE") ||
      ((this.state === "ACCEPTED" || this.state === "REJECTED") &&
        type === "CLEAR");

    if (!allowed) {
      throw new Error(`invalid transition: ${this.state} -> ${type}`);
    }

    if (type === "START") {
      this.documentId = nextDocumentId;
      this.decisionNote = null;
      this.state = "REVIEWING";
    } else if (type === "DECIDE") {
      this.decisionNote = note;
      this.state = approved === true ? "ACCEPTED" : "REJECTED";
    } else {
      this.state = "IDLE";
      this.documentId = null;
      this.decisionNote = null;
    }

    return this.view();
  }

  view(): ReviewView {
    return {
      state: this.state,
      documentId: this.documentId,
      decisionNote: this.decisionNote,
    };
  }
}

