}

const cycle = new ReviewCycle();
assertView(cycle.view(), { state: "IDLE", documentId: null, decisionNote: null }, "new cycle must be idle");

expectError("command must be an object", () => cycle.apply(null));
expectError("command must be an object", () => cycle.apply([]));
expectError("command must be an object", () => cycle.apply("START"));
expectError("command must be an object", () => cycle.apply(false));
expectError("type must be START, DECIDE, or CLEAR", () => cycle.apply({}));
expectError("type must be START, DECIDE, or CLEAR", () => cycle.apply({ type: "PACK" }));
expectError("type must be START, DECIDE, or CLEAR", () => cycle.apply({ type: null }));
expectError("START.documentId must be a non-empty string", () => cycle.apply({ type: "START", documentId: "\t " }));
expectError("START.documentId must be a non-empty string", () => cycle.apply({ type: "START", documentId: 12 }));
expectError("DECIDE.approved must be a boolean", () => cycle.apply({ type: "DECIDE", approved: "yes", note: "valid" }));
expectError("DECIDE.note must be a non-empty string", () => cycle.apply({ type: "DECIDE", approved: true, note: "  " }));
expectError("DECIDE.note must be a non-empty string", () => cycle.apply({ type: "DECIDE", approved: false, note: 1 }));
assertView(cycle.view(), { state: "IDLE", documentId: null, decisionNote: null }, "malformed commands must not change the cycle");

expectError("invalid transition: IDLE -> DECIDE", () => cycle.apply({ type: "DECIDE", approved: true, note: "ready" }));
expectError("DECIDE.approved must be a boolean", () => cycle.apply({ type: "DECIDE", approved: 1, note: "ready" }));
assertView(cycle.view(), { state: "IDLE", documentId: null, decisionNote: null }, "failed IDLE commands must preserve all fields");

assertView(
  cycle.apply({ type: "START", documentId: " doc-1 ", ignored: 4 }),
  { state: "REVIEWING", documentId: " doc-1 ", decisionNote: null },
  "START must store the document ID and ignore additional properties",
);
expectError("START.documentId must be a non-empty string", () => cycle.apply({ type: "START", documentId: "" }));
expectError("invalid transition: REVIEWING -> START", () => cycle.apply({ type: "START", documentId: "doc-2" }));
expectError("invalid transition: REVIEWING -> CLEAR", () => cycle.apply({ type: "CLEAR" }));
assertView(cycle.view(), { state: "REVIEWING", documentId: " doc-1 ", decisionNote: null }, "invalid transitions must preserve review data");

assertView(
  cycle.apply({ type: "DECIDE", approved: true, note: " approved ", extra: true }),
  { state: "ACCEPTED", documentId: " doc-1 ", decisionNote: " approved " },
  "an approved decision must reach ACCEPTED and retain its note",
);
expectError("DECIDE.note must be a non-empty string", () => cycle.apply({ type: "DECIDE", approved: false, note: "" }));
expectError("invalid transition: ACCEPTED -> DECIDE", () => cycle.apply({ type: "DECIDE", approved: false, note: "changed" }));
assertView(cycle.view(), { state: "ACCEPTED", documentId: " doc-1 ", decisionNote: " approved " }, "failed terminal commands must preserve accepted data");
assertView(cycle.apply({ type: "CLEAR" }), { state: "IDLE", documentId: null, decisionNote: null }, "CLEAR must reset an accepted cycle");

cycle.apply({ type: "START", documentId: "doc-2" });
assertView(
  cycle.apply({ type: "DECIDE", approved: false, note: "needs changes" }),
  { state: "REJECTED", documentId: "doc-2", decisionNote: "needs changes" },
  "a rejected decision must reach REJECTED",
);
assertView(cycle.apply({ type: "CLEAR", ignored: true }), { state: "IDLE", documentId: null, decisionNote: null }, "CLEAR must reset a rejected cycle and ignore extra properties");
expectError("invalid transition: IDLE -> CLEAR", () => cycle.apply({ type: "CLEAR" }));
assertView(cycle.view(), { state: "IDLE", documentId: null, decisionNote: null }, "failed CLEAR must leave the cycle idle");

