import { TextAccumulator } from "./solution";

function assertDeepEqual(actual: unknown, expected: unknown, message: string): void {
  const actualJson = JSON.stringify(actual);
  const expectedJson = JSON.stringify(expected);
  if (actualJson !== expectedJson) {
    throw new Error(`${message}: expected ${expectedJson}, received ${actualJson}`);
  }
}

const first = new TextAccumulator();
assertDeepEqual(
  first.snapshot(),
  { text: "", codePoints: 0, words: 0 },
  "new accumulator is empty"
);

const ignored = first.append("\t\u2003\u00A0\n");
assertDeepEqual(
  ignored,
  { text: "", codePoints: 0, words: 0 },
  "whitespace-only fragments are ignored"
);

const earlySnapshot = first.append("  Ａ\u00A0ﬁ  ");
assertDeepEqual(
  earlySnapshot,
  { text: "A fi", codePoints: 4, words: 2 },
  "append applies NFKC and collapses Unicode whitespace"
);

assertDeepEqual(
  first.append("😀e\u0301"),
  { text: "A fi 😀é", codePoints: 7, words: 3 },
  "code points do not count an emoji surrogate pair twice"
);

assertDeepEqual(
  first.append("  one\t\n\u2003two  "),
  { text: "A fi 😀é one two", codePoints: 15, words: 5 },
  "fragments are joined by exactly one ASCII space"
);

assertDeepEqual(
  earlySnapshot,
  { text: "A fi", codePoints: 4, words: 2 },
  "an earlier snapshot remains stable after later appends"
);

const second = new TextAccumulator();
assertDeepEqual(
  second.append("\u0301"),
  { text: "\u0301", codePoints: 1, words: 1 },
  "a combining-mark run counts as a word"
);
assertDeepEqual(
  first.snapshot(),
  { text: "A fi 😀é one two", codePoints: 15, words: 5 },
  "instances own independent state"
);

assertDeepEqual(
  second.append("\uD800"),
  { text: "\u0301 \uD800", codePoints: 3, words: 1 },
  "an unpaired surrogate is retained but is not a word"
);

assertDeepEqual(
  first.clear(),
  { text: "", codePoints: 0, words: 0 },
  "clear returns the empty snapshot"
);
assertDeepEqual(
  first.snapshot(),
  { text: "", codePoints: 0, words: 0 },
  "clear empties the accumulator"
);
assertDeepEqual(
  second.snapshot(),
  { text: "\u0301 \uD800", codePoints: 3, words: 1 },
  "clearing one instance does not affect another"
);

