import { CodePointTape } from "./solution";

function assertEqual(actual: unknown, expected: unknown, message: string): void {
  if (actual !== expected) {
    throw new Error(`${message}: expected ${String(expected)}, received ${String(actual)}`);
  }
}

const empty = new CodePointTape();
assertEqual(empty.value(), "", "default seed is empty");
assertEqual(empty.length(), 0, "empty tape has zero code points");
assertEqual(empty.pop(), undefined, "pop on an empty tape returns undefined");
assertEqual(empty.value(), "", "empty pop does not mutate the tape");

const seeded = new CodePointTape("e\u0301😀");
assertEqual(seeded.value(), "é😀", "seed is normalized to NFC");
assertEqual(seeded.length(), 2, "length counts Unicode code points");
assertEqual(seeded.pop(), "😀", "pop returns the final supplementary code point intact");
assertEqual(seeded.value(), "é", "pop removes exactly one code point");
assertEqual(seeded.pop(), "é", "pop returns the remaining code point");
assertEqual(seeded.pop(), undefined, "tape becomes empty after all code points are popped");

const acrossBoundary = new CodePointTape("e");
assertEqual(
  acrossBoundary.append("\u0301"),
  1,
  "append normalizes the entire concatenated value"
);
assertEqual(acrossBoundary.value(), "é", "composition can occur across the append boundary");
assertEqual(acrossBoundary.append("😀x"), 3, "append returns the new code-point count");
assertEqual(acrossBoundary.length(), 3, "length agrees with append result");

const independent = new CodePointTape("other");
acrossBoundary.clear();
assertEqual(acrossBoundary.value(), "", "clear empties the selected tape");
assertEqual(acrossBoundary.length(), 0, "cleared tape has zero length");
assertEqual(independent.value(), "other", "clearing one tape does not affect another");

const malformed = new CodePointTape("\uD800A");
assertEqual(malformed.length(), 2, "an unpaired surrogate is treated as one code point");
assertEqual(malformed.pop(), "A", "ordinary final code point is popped first");
assertEqual(malformed.pop(), "\uD800", "unpaired surrogate can be removed without other mutation");
assertEqual(malformed.length(), 0, "malformed tape can be fully emptied");

