def aggregate_dispatches(records):
    hubs = {}

    for record in records:
        hub = record["hub"]
        sku = record["sku"]
        units = record["units"]

        if hub not in hubs:
            hubs[hub] = {"total_units": 0, "skus": {}}

        group = hubs[hub]
        group["total_units"] += units
        group["skus"][sku] = group["skus"].get(sku, 0) + units

    result = []
    for hub, group in hubs.items():
        items = [
            {"sku": sku, "units": units}
            for sku, units in group["skus"].items()
        ]
        result.append(
            {
                "hub": hub,
                "total_units": group["total_units"],
                "items": items,
            }
        )

    return result

