import copy
import unittest

import solution


class AggregateDispatchesTests(unittest.TestCase):
    def test_aggregates_duplicates_and_preserves_first_seen_order(self):
        records = [
            {"hub": "south", "sku": "B2", "units": 3},
            {"hub": "north", "sku": "A7", "units": 4},
            {"hub": "south", "sku": "A7", "units": 2},
            {"hub": "north", "sku": "A7", "units": 5},
            {"hub": "south", "sku": "B2", "units": 6},
            {"hub": "north", "sku": "C1", "units": 0},
        ]
        self.assertEqual(
            solution.aggregate_dispatches(records),
            [
                {
                    "hub": "south",
                    "total_units": 11,
                    "items": [
                        {"sku": "B2", "units": 9},
                        {"sku": "A7", "units": 2},
                    ],
                },
                {
                    "hub": "north",
                    "total_units": 9,
                    "items": [
                        {"sku": "A7", "units": 9},
                        {"sku": "C1", "units": 0},
                    ],
                },
            ],
        )

    def test_empty_input(self):
        self.assertEqual(solution.aggregate_dispatches([]), [])

    def test_zero_and_large_unit_boundaries(self):
        records = [
            {"hub": "edge", "sku": "zero", "units": 0},
            {"hub": "edge", "sku": "large", "units": 10**30},
            {"hub": "edge", "sku": "large", "units": 10**30},
        ]
        self.assertEqual(
            solution.aggregate_dispatches(records),
            [{
                "hub": "edge",
                "total_units": 2 * 10**30,
                "items": [
                    {"sku": "zero", "units": 0},
                    {"sku": "large", "units": 2 * 10**30},
                ],
            }],
        )

    def test_input_is_not_modified_and_calls_are_isolated(self):
        records = [
            {"hub": "h", "sku": "x", "units": 2},
            {"hub": "h", "sku": "x", "units": 3},
        ]
        original = copy.deepcopy(records)
        first = solution.aggregate_dispatches(records)
