def encode_flag_table(entries: list[tuple[int, int]]) -> bytes:
    combined: dict[int, int] = {}
    for channel, mask in entries:
        combined[channel] = combined.get(channel, 0) | mask

    encoded = bytearray()
    for channel in sorted(combined):
        mask = combined[channel]
        encoded.append((channel << 4) | (mask >> 8))
        encoded.append(mask & 0xFF)

    checksum = 0
    for value in encoded:
        checksum ^= value
    encoded.append(checksum)
    return bytes(encoded)

