def _split_encoded(line):
    escaped = False
    for index, character in enumerate(line):
        if escaped:
            escaped = False
        elif character == "\\":
            escaped = True
        elif character == "=":
            return line[:index], line[index + 1:]


def _decode(value):
    decoded = []
    escaped = False
    for character in value:
        if escaped:
            decoded.append(character)
            escaped = False
        elif character == "\\":
            escaped = True
        else:
            decoded.append(character)
    return "".join(decoded)


def parse_property_text(text):
    properties = {}
    for line in text.splitlines():
        if not line.strip():
            continue
        encoded_key, encoded_value = _split_encoded(line)
        key = _decode(encoded_key.strip()).lower()
        value = _decode(encoded_value.strip())
        properties.setdefault(key, []).append(value)
    return properties

