def apply_splices(sequence, edits):
    if not isinstance(sequence, list) or not isinstance(edits, list):
        raise ValueError("arguments must be lists")

    result = []
    cursor = 0
    previous_start = -1

    for edit in edits:
        if not isinstance(edit, tuple) or len(edit) != 3:
            raise ValueError("each edit must be a 3-tuple")
        start, delete_count, replacement = edit
        if type(start) is not int or type(delete_count) is not int:
            raise ValueError("indices must be integers")
        if not isinstance(replacement, list):
            raise ValueError("replacement must be a list")
        if start < 0 or start > len(sequence):
            raise ValueError("start out of bounds")
        if delete_count < 0 or delete_count > len(sequence) - start:
            raise ValueError("delete count out of bounds")
        if start < previous_start:
            raise ValueError("edits are out of order")
        if start < cursor:
            raise ValueError("edits overlap")

        result.extend(sequence[cursor:start])
        result.extend(replacement)
        cursor = start + delete_count
        previous_start = start

    result.extend(sequence[cursor:])
    return result

