def make_job_registry():
    jobs = {}

    def dispatch(job_id, operation, value=None):
        if operation == "create":
            if job_id in jobs:
                raise ValueError("job already exists")
            jobs[job_id] = {"state": "collecting", "parts": []}
            return None

        if job_id not in jobs:
            raise KeyError(job_id)

        job = jobs[job_id]

        if operation == "get":
            return _copy.deepcopy(job)

        if operation == "add":
            if job["state"] != "collecting":
                raise ValueError("add requires collecting state")
            job["parts"].append(_copy.deepcopy(value))
            return None

        if operation == "finalize":
            if job["state"] != "collecting":
                raise ValueError("finalize requires collecting state")
            job["state"] = "finalized"
            return _copy.deepcopy(job["parts"])

        if operation == "cancel":
            if job["state"] != "collecting":
                raise ValueError("cancel requires collecting state")
            job["state"] = "cancelled"
            job["parts"] = []
            return None

        raise ValueError("unknown operation")

    return dispatch

