def replay_workflows(initial_states, events):
    states = dict(initial_states)
    seen = set()

    for event_id, workflow_id, action in events:
        if event_id in seen:
            continue
        seen.add(event_id)

        if action == "start" and states[workflow_id] == "new":
            states[workflow_id] = "active"
        elif action == "finish" and states[workflow_id] == "active":
            states[workflow_id] = "complete"
        else:
            raise ValueError("invalid transition")

    return states

