from solution import canonical_alias_index


class CanonicalAliasIndexTests(unittest.TestCase):
    def test_empty_input(self):
        self.assertEqual(canonical_alias_index({}), {})

    def test_canonicalizes_names_and_aliases(self):
        groups = {
            "  Ｔｅａｍ\tONE ": [" Café ", "STRASSE", "①\u00a0North"],
        }
        self.assertEqual(
            canonical_alias_index(groups),
            {"team one": ("café", "strasse", "1 north")},
        )

    def test_colliding_group_names_merge_in_iteration_order(self):
        groups = {
            "Alpha": [" First ", "DUP", "", "\t\n"],
            "ＡＬＰＨＡ": ["dup", "Second", "FIRST"],
            " alpha ": [" third ", "second"],
        }
        result = canonical_alias_index(groups)
        self.assertEqual(list(result), ["alpha"])
        self.assertEqual(result, {"alpha": ("first", "dup", "second", "third")})

    def test_empty_canonical_group_name_is_retained(self):
        groups = {"\t\u3000": [" Value ", "  "]}
        self.assertEqual(canonical_alias_index(groups), {"": ("value",)})

    def test_input_is_not_mutated_and_result_does_not_borrow_lists(self):
        aliases = [" One ", "ＴＷＯ", "one"]
        groups = {" Group ": aliases}
        original_aliases = list(aliases)
        original_items = list(groups.items())

        result = canonical_alias_index(groups)

        self.assertEqual(result, {"group": ("one", "two")})
        self.assertIsInstance(result["group"], tuple)
        self.assertEqual(aliases, original_aliases)
        self.assertEqual(list(groups.items()), original_items)

        aliases[:] = ["changed"]
        groups["new"] = ["alias"]
        self.assertEqual(result, {"group": ("one", "two")})

    def test_casefold_duplicates_and_whitespace_runs(self):
        groups = {"Straße": [" A\u00a0\tB ", "a b", "Straße", "STRASSE"]}
        self.assertEqual(
            canonical_alias_index(groups),
            {"strasse": ("a b", "strasse")},
        )


if __name__ == "__main__":
    unittest.main()

