import unittest

from solution import decode_braced_unicode


class DecodeBracedUnicodeTests(unittest.TestCase):
    def test_empty_and_plain_text(self):
        self.assertEqual(decode_braced_unicode(""), "")
        self.assertEqual(decode_braced_unicode("plain text"), "plain text")

    def test_decodes_valid_candidates_and_literal_backslashes(self):
        text = r"A\u{41} \u{1f642} \\ end"
        self.assertEqual(decode_braced_unicode(text), "AA 🙂 \\ end")

    def test_scalar_boundaries(self):
        self.assertEqual(decode_braced_unicode(r"\u{0}"), "\x00")
        self.assertEqual(decode_braced_unicode(r"\u{10FFFF}"), chr(0x10FFFF))
        self.assertEqual(decode_braced_unicode(r"\u{d7ff}\u{e000}"), "\ud7ff\ue000")

    def test_invalid_candidates_are_copied_verbatim(self):
        invalid = [
            r"\u{}",
            r"\u{1234567}",
            r"\u{12G}",
            r"\u{110000}",
            r"\u{D800}",
            r"\u{dfff}",
        ]
        for candidate in invalid:
            with self.subTest(candidate=candidate):
                self.assertEqual(decode_braced_unicode(candidate), candidate)

    def test_first_closing_brace_ends_candidate(self):
        text = r"x\u{41}tail}y\u{4}2}"
        self.assertEqual(decode_braced_unicode(text), "xAtail}y\x042}")

    def test_missing_closing_brace_copies_complete_suffix(self):
        text = r"prefix\u{41 suffix\\still"
        self.assertEqual(decode_braced_unicode(text), text)

    def test_unknown_sequences_and_final_backslash_are_verbatim(self):
        text = "\\q\\u41\\"
        self.assertEqual(decode_braced_unicode(text), text)

    def test_escaped_backslash_prevents_unicode_candidate_decoding(self):
        text = r"\\u{41}"
        self.assertEqual(decode_braced_unicode(text), r"\u{41}")

    def test_invalid_candidate_does_not_prevent_later_decoding(self):
        text = r"\u{xyz}\u{42}"
        self.assertEqual(decode_braced_unicode(text), r"\u{xyz}B")


if __name__ == "__main__":
    unittest.main()

