class CanonicalSearchKeyTests(unittest.TestCase):
    def test_empty_and_separator_only_inputs(self):
        self.assertEqual(canonical_search_key(""), "")
        self.assertEqual(canonical_search_key(" \t—_!?\n"), "")

    def test_nfkd_casefold_marks_and_separator_collapsing(self):
        text = "  Café—NAÏVE...Straße  "
        self.assertEqual(canonical_search_key(text), "cafe naive strasse")

    def test_letters_numbers_and_compatibility_characters(self):
        text = "Ｆｏｏ ① Ⅳ A_2"
        self.assertEqual(canonical_search_key(text), "foo 1 iv a 2")

    def test_combining_marks_are_discarded_without_becoming_separators(self):
        text = "a\u0301\u0327b x\u0308-y"
        self.assertEqual(canonical_search_key(text), "ab x y")

    def test_unpaired_surrogates_become_visible_replacement_characters(self):
        cases = [
            ("a\ud800b", "a�b"),
            ("\udfff", "�"),
            ("x-\udabc-y", "x � y"),
        ]
        for text, expected in cases:
            with self.subTest(text=repr(text)):
                self.assertEqual(canonical_search_key(text), expected)

    def test_existing_replacement_character_is_retained_as_content(self):
        self.assertEqual(canonical_search_key(" A�B "), "a�b")
        self.assertEqual(canonical_search_key("a-�-b"), "a � b")

