mod solution;

use solution::combined_counts;
use std::collections::BTreeMap;

fn map(entries: &[(&str, u64)]) -> BTreeMap<String, u64> {
    entries
        .iter()
        .map(|(key, value)| ((*key).to_string(), *value))
        .collect()
}

#[test]
fn empty_maps_produce_empty_map() {
    let mut primary = BTreeMap::new();
    let secondary = BTreeMap::new();

    assert_eq!(combined_counts(&mut primary, &secondary), BTreeMap::new());
}

#[test]
fn combines_overlapping_and_disjoint_keys() {
    let mut primary = map(&[("apple", 4), ("pear", 7)]);
    let secondary = map(&[("apple", 6), ("banana", 3)]);

    assert_eq!(
        combined_counts(&mut primary, &secondary),
        map(&[("apple", 10), ("banana", 3), ("pear", 7)])
    );
}

#[test]
fn retains_keys_whose_counts_are_zero() {
    let mut primary = map(&[("from-primary", 0)]);
    let secondary = map(&[("from-secondary", 0)]);

    assert_eq!(
        combined_counts(&mut primary, &secondary),
        map(&[("from-primary", 0), ("from-secondary", 0)])
