fn neither_input_map_is_changed() {
    let mut primary = map(&[("z", 1), ("a", 2)]);
    let secondary = map(&[("z", 8), ("m", 5)]);
    let primary_before = primary.clone();
    let secondary_before = secondary.clone();

    let first = combined_counts(&mut primary, &secondary);
    assert_eq!(primary, primary_before);
    assert_eq!(secondary, secondary_before);

    let second = combined_counts(&mut primary, &secondary);
