    assert_eq!(apportion(&[1, 1, 1, 1], 2), Some(vec![1, 1, 0, 0]));
    assert_eq!(apportion(&[1, 1, 1], 5), Some(vec![2, 2, 1]));
}

#[test]
fn zero_weight_positions_receive_nothing() {
    assert_eq!(apportion(&[0, 5, 0], 7), Some(vec![0, 7, 0]));
}

#[test]
fn positive_weights_with_zero_total_receive_zero() {
    assert_eq!(apportion(&[9, 1, 4], 0), Some(vec![0, 0, 0]));
}

#[test]
fn handles_multiplication_and_sum_beyond_u64() {
    assert_eq!(
        apportion(&[u64::MAX, u64::MAX], u64::MAX),
        Some(vec![9_223_372_036_854_775_808, 9_223_372_036_854_775_807])
    );

    assert_eq!(
        apportion(&[u64::MAX, 1], u64::MAX),
        Some(vec![u64::MAX - 1, 1])
    );
}

