fn returns_one_allocation_per_weight_and_preserves_input() {
    let weights = vec![7, 0, 11, 3];
    let original = weights.clone();
    let allocations = apportion(&weights, 1_000).expect("positive weight sum");

    assert_eq!(allocations.len(), weights.len());
    assert_eq!(allocations.iter().copied().sum::<u64>(), 1_000);
    assert_eq!(weights, original);
}

