#[path = "solution.rs"]
mod solution;

use solution::BinaryOverlap;

fn assert_close(actual: f64, expected: f64) {
    assert!(
        (actual - expected).abs() < 1e-12,
        "expected {expected}, got {actual}"
    );
}

#[test]
fn empty_slices_are_a_perfect_overlap() {
    let mut overlap = BinaryOverlap::new();
    assert_eq!(overlap.score(&[], &[]), (1.0, 1.0));
}

#[test]
fn computes_both_requested_scores() {
    let mut overlap = BinaryOverlap::new();
    let left = [true, true, true, false];
    let right = [true, true, false, true];

    let (first, second) = overlap.score(&left, &right);
    assert_close(first, 2.0 / 3.0);
    assert_close(second, 0.5);
}

#[test]
fn no_shared_true_positions_scores_zero() {
    let mut overlap = BinaryOverlap::new();
    assert_eq!(
        overlap.score(&[true, false, true], &[false, true, false]),
        (0.0, 0.0)
    );
}

#[test]
fn each_call_is_independent_of_previous_calls() {
    let mut overlap = BinaryOverlap::new();

    assert_eq!(overlap.score(&[true, true], &[true, true]), (1.0, 1.0));
    assert_eq!(overlap.score(&[], &[]), (1.0, 1.0));
    assert_eq!(overlap.score(&[true], &[false]), (0.0, 0.0));
    assert_eq!(overlap.score(&[false], &[false]), (1.0, 1.0));
}

#[test]
fn scoring_does_not_mutate_inputs() {
    let mut overlap = BinaryOverlap::new();
    let left = vec![true, false, true, false];
    let right = vec![false, true, true, false];
    let left_before = left.clone();
    let right_before = right.clone();

    let _ = overlap.score(&left, &right);
    assert_eq!(left, left_before);
    assert_eq!(right, right_before);
}

