pub fn select_label(labels: &mut [String], rank: usize) -> Option<&str> {
    if rank >= labels.len() {
        return None;
    }

    let mut indices: Vec<usize> = (0..labels.len()).collect();
    indices.sort_by(|&left, &right| {
        labels[left]
            .len()
            .cmp(&labels[right].len())
            .then_with(|| labels[left].cmp(&labels[right]))
            .then_with(|| left.cmp(&right))
    });

    Some(labels[indices[rank]].as_str())
}

