#[derive(Debug, Clone, PartialEq, Eq)]
pub enum QueryError {
    MissingEquals,
    ExtraEquals,
    InvalidCharacter,
    InvalidEscape,
    InvalidUtf8,
}

fn unreserved(b: u8) -> bool {
    b.is_ascii_alphanumeric() || matches!(b, b'-' | b'.' | b'_' | b'~')
}

fn hex_value(b: u8) -> Option<u8> {
    match b {
        b'0'..=b'9' => Some(b - b'0'),
        b'a'..=b'f' => Some(b - b'a' + 10),
        b'A'..=b'F' => Some(b - b'A' + 10),
        _ => None,
    }
}

fn decode(raw: &str) -> Result<String, QueryError> {
    let bytes = raw.as_bytes();
    let mut out = Vec::new();
    let mut i = 0;
    while i < bytes.len() {
        if bytes[i] == b'%' {
            if i + 2 >= bytes.len() {
                return Err(QueryError::InvalidEscape);
            }
            let hi = hex_value(bytes[i + 1]).ok_or(QueryError::InvalidEscape)?;
            let lo = hex_value(bytes[i + 2]).ok_or(QueryError::InvalidEscape)?;
            out.push((hi << 4) | lo);
            i += 3;
        } else if unreserved(bytes[i]) {
            out.push(bytes[i]);
            i += 1;
        } else {
            return Err(QueryError::InvalidCharacter);
        }
    }
    String::from_utf8(out).map_err(|_| QueryError::InvalidUtf8)
