    assert_eq!(rolling_totals(&empty, 4), Vec::<Vec<i128>>::new());

    let batches = vec![vec![], vec![2, 2], vec![]];
    assert_eq!(
        rolling_totals(&batches, 4),
        vec![vec![], vec![2_i128, 4], vec![]]
