mod solution;

use solution::interleave_first_occurrences;

fn strings(values: &[&str]) -> Vec<String> {
    values.iter().map(|value| (*value).to_string()).collect()
}

#[test]
fn interleaves_values_in_index_order() {
    let left = strings(&["l0", "l1", "l2"]);
    let right = strings(&["r0", "r1", "r2"]);

    assert_eq!(
        interleave_first_occurrences(&left, &right),
        strings(&["l0", "r0", "l1", "r1", "l2", "r2"])
    );
}

#[test]
fn suppresses_non_adjacent_duplicates_across_both_sides() {
    let left = strings(&["alpha", "beta", "right-only", "alpha"]);
    let right = strings(&["gamma", "alpha", "beta", "delta"]);

    assert_eq!(
        interleave_first_occurrences(&left, &right),
        strings(&["alpha", "gamma", "beta", "right-only", "delta"])
    );
}

#[test]
fn handles_empty_and_uneven_inputs() {
    let empty: Vec<String> = Vec::new();
    assert_eq!(interleave_first_occurrences(&empty, &empty), empty);

    let left = strings(&["a"]);
    let right = strings(&["b", "c", "b", "d"]);
    assert_eq!(
        interleave_first_occurrences(&left, &right),
        strings(&["a", "b", "c", "d"])
    );

    let only_left = strings(&["x", "y", "x", "z"]);
    assert_eq!(
        interleave_first_occurrences(&only_left, &[]),
        strings(&["x", "y", "z"])
    );
}

#[test]
fn comparison_is_exact_case_sensitive_and_supports_empty_strings() {
    let left = strings(&["", "Case", "é", "Case"]);
    let right = strings(&["case", "", "É", "é"]);

    assert_eq!(
        interleave_first_occurrences(&left, &right),
        strings(&["", "case", "Case", "é", "É"])
    );
}

#[test]
fn first_appearance_determines_retained_position() {
    let left = strings(&["shared", "later-left"]);
    let right = strings(&["shared", "later-left", "right-tail"]);

    assert_eq!(
        interleave_first_occurrences(&left, &right),
        strings(&["shared", "later-left", "right-tail"])
    );
}

#[test]
fn inputs_are_not_modified_and_results_are_owned_and_stable() {
    let left = strings(&["a", "b", "a"]);
    let right = strings(&["c", "b"]);
    let left_before = left.clone();
    let right_before = right.clone();

    let first = interleave_first_occurrences(&left, &right);
    let second = interleave_first_occurrences(&left, &right);

    assert_eq!(first, second);
    assert_eq!(left, left_before);
    assert_eq!(right, right_before);

    let mut changed_left = left;
    changed_left[0].push_str("-changed");
    assert_eq!(first, strings(&["a", "c", "b"]));
}

