#[path = "solution.rs"]
mod solution;

use solution::{ApplyError, Phase, Workflow};

#[test]
fn successful_script_reaches_completed_with_name_and_count() {
    let mut workflow = Workflow::new();

    assert_eq!(workflow.apply_script("start forge\nadvance\nadvance\nfinish"), Ok(()));
    assert_eq!(
        workflow.phase(),
        &Phase::Completed {
            name: "forge".to_owned(),
            advances: 2,
        }
    );
}

#[test]
fn empty_script_is_a_no_op() {
    let mut workflow = Workflow::new();

    assert_eq!(workflow.apply_script(""), Ok(()));
    assert_eq!(workflow.phase(), &Phase::Idle);
}

#[test]
fn malformed_command_rolls_back_all_preceding_commands() {
