#[path = "solution.rs"]
mod solution;

use solution::titlecase_records;

fn strings(values: &[&str]) -> Vec<String> {
    values.iter().map(|value| (*value).to_owned()).collect()
}

#[test]
fn empty_input_and_empty_records_are_preserved() {
    assert_eq!(titlecase_records(&[]), Vec::<String>::new());
    assert_eq!(titlecase_records(&["", ""]), strings(&["", ""]));
}

#[test]
fn titlecases_each_whitespace_delimited_word_without_lowercasing_the_rest() {
    assert_eq!(
        titlecase_records(&["hello world", "hELLO wORLD"]),
        strings(&["Hello World", "HELLO WORLD"])
    );
}

#[test]
fn preserves_unicode_whitespace_exactly() {
    assert_eq!(
        titlecase_records(&["alpha\tbeta\nγamma{nbsp}delta{em_space}echo"]),
        strings(&["Alpha\tBeta\nΓamma{nbsp}Delta{em_space}Echo"])
    );
}

#[test]
fn uses_complete_uppercase_expansion_at_word_start() {
    assert_eq!(
        titlecase_records(&["ßeta straße", "ﬃle"]),
        strings(&["SSeta Straße", "FFIle"])
    );
}

#[test]
fn word_start_state_resets_for_every_record() {
    assert_eq!(
        titlecase_records(&["alpha", "beta", "γamma"]),
        strings(&["Alpha", "Beta", "Γamma"])
    );
}

#[test]
fn empty_record_does_not_prevent_next_record_from_starting_a_word() {
    assert_eq!(
        titlecase_records(&["first", "", "second"]),
        strings(&["First", "", "Second"])
    );
}

#[test]
fn leading_and_trailing_whitespace_are_retained() {
    assert_eq!(
        titlecase_records(&["  alpha\t", "\nßeta{nbsp}"]),
        strings(&["  Alpha\t", "\nSSeta{nbsp}"])
    );
}

#[test]
fn source_records_are_not_mutated() {
    let records = ["alpha beta", "ßeta"];
    let before = records;

    let result = titlecase_records(&records);

    assert_eq!(result, strings(&["Alpha Beta", "SSeta"]));
    assert_eq!(records, before);
}

